// プレイヤー画像は配布版でassetsフォルダを削除しても表示できるよう、埋め込みデータを使用する。
const PLAYER_IMAGE_ASSET = GAME_IMAGES.img_001;
function ensurePlayerImageVisible() {
 document.querySelectorAll('.player-img').forEach((img) => {
  if (!img || img.src === PLAYER_IMAGE_ASSET) return;
  const current = img.getAttribute('src') || '';
  if (!current || current.startsWith('assets/')) {
   img.src = PLAYER_IMAGE_ASSET;
  }
  img.onerror = () => {
   img.onerror = null;
   img.src = PLAYER_IMAGE_ASSET;
  };
 });
}
if (document.readyState === 'loading') {
 document.addEventListener('DOMContentLoaded', ensurePlayerImageVisible);
} else {
 ensurePlayerImageVisible();
}

