  function buildCurrentSaveSnapshot() {
   return normalizeSaveData({
    playerName: getCurrentPlayerName(),
    discoveredEnemies: loadRuntimeDiscoveryMap(ENCOUNTERED_ENEMIES_STORAGE_KEY),
    discoveredCards: loadDiscoveredCards(),
    discoveredPassives: loadRuntimeDiscoveryMap(DISCOVERED_PASSIVES_STORAGE_KEY),
    evolvedPets: loadRuntimeDiscoveryMap(EVOLVED_PETS_STORAGE_KEY),
    achievements: loadAchievements(),
    achievementStats: loadAchievementStats(),
    battleHistory: loadBattleHistory(),
    deckPresets: loadCustomDeckPresets(),
    randomEvents: loadRandomEventProgress(),
    relics: loadRelicProgress(),
    relicEquipment: loadRelicEquipment(),
    deckCustomize: sanitizeDeckCustomize(savedDeckCustomize),
    selectedPetId,
    petLevel: getPetLevelFromExp(petExp),
    petExp: normalizePetExp(petExp),
    currentDepth,
    depthProgress: loadDepthProgress(),
   });
  }

  function saveCurrentGameData(showMessage = true, slot = currentSaveSlot) {
   slot = Number(slot);
   if (!isValidSaveSlot(slot)) {
    if (showMessage) showSaveSlotScreen();
    return false;
   }

   const snapshot = buildCurrentSaveSnapshot();
   const saved = writeSaveData(snapshot, slot);
   const savedSlot = readSaveSlot(slot);

   if (!saved || !savedSlot) {
    if (showMessage) {
     alert('セーブに失敗しました。ブラウザでlocalStorageが無効になっている可能性があります。');
    }
    return false;
   }

   currentSaveSlot = slot;

   if (showMessage) {
    addLog(`スロット${slot}にセーブしました`);
    alert(`スロット${slot}にセーブしました`);
   }

   return true;
  }

  function saveCurrentGameDataToSlot(slot) {
   playUiSelectSound();
   const saved = saveCurrentGameData(true, slot);
   if (saved) currentScreen = 'title';
   render();
  }

  function saveFromTitleMenu() {
   showSaveSlotScreen();
  }

  function getDefaultAchievementStats() {
   return {
    totalBattles: 0,
    totalWins: 0,
    totalLosses: 0,
    totalCardsUsed: 0,
    totalDamageDealt: 0,
    totalDamageTaken: 0,
    noDamageWins: 0,
    hpOneWins: 0,
    highestLevel: 0,
    criticalHits: 0,
    highestSingleHit: 0,
    reflectDamage: 0,
    reflectKills: 0,
    freezeDamage: 0,
    freezeHits: 0,
    freezeApplications: 0,
    burnApplications: 0,
    burnHalves: 0,
    statusGuards: 0,
    totalReloads: 0,
    totalEnemyDelaySeconds: 0,
    maxBlock: 0,
    maxCardsUsedInBattle: 0,
    chaosHandUses: 0,
    echoUses: 0,
    fortuneUses: 0,
    level20Wins: 0,
    cardDiscoveries: 0,
    depth1Clears: 0,
    depth2Clears: 0,
    depth3Clears: 0,
    bombPlacements: 0,
    bombExplosions: 0,
    bombExplosionDamage: 0,
    poisonApplications: 0,
    poisonAppliedTotal: 0,
    maxPoisonAmount: 0,
    poisonBanquetUses: 0,
    petExpGained: 0,
    highestPetLevel: 1,
    randomEventAcceptedTotal: 0,
    randomEventRejectedTotal: 0,
   };
  }

  function normalizeAchievementStats(value) {
   const base = getDefaultAchievementStats();
   const source = value && typeof value === 'object' ? value : {};

   Object.keys(base).forEach(key => {
    const num = Number(source[key]);
    base[key] = Number.isFinite(num) && num > 0 ? Math.floor(num) : 0;
   });

   return base;
  }


  function normalizeBattleHistory(value) {
   if (!Array.isArray(value)) return [];

   return value
    .filter(item => item && typeof item === 'object')
    .slice(0, MAX_BATTLE_HISTORY_COUNT)
    .map(item => ({
     id: String(item.id || `history-${Date.now()}-${Math.random().toString(16).slice(2)}`),
     recordedAt: Number(item.recordedAt || Date.now()),
     result: ['win', 'lose', 'progress'].includes(item.result) ? item.result : 'lose',
     depth: normalizeDepth(item.depth || item.currentDepth || 1),
     runStartedAt: Number(item.runStartedAt || item.recordedAt || Date.now()),
     reachedLevel: Math.max(1, Number(item.reachedLevel || 1)),
     playTimeMs: Math.max(0, Number(item.playTimeMs || 0)),
     cardsUsed: Math.max(0, Number(item.cardsUsed || 0)),
     damageDealt: Math.max(0, Number(item.damageDealt || 0)),
     damageTaken: Math.max(0, Number(item.damageTaken || 0)),
     remainingHp: Math.max(0, Number(item.remainingHp || 0)),
     petId: String(item.petId || 'none'),
     petName: String(item.petName || 'なし'),
     deck: item.deck && typeof item.deck === 'object' ? item.deck : {},
     passives: Array.isArray(item.passives) ? item.passives : [],
     enemies: Array.isArray(item.enemies)
      ? item.enemies
       .filter(enemy => enemy && typeof enemy === 'object')
       .map(enemy => ({
        level: Math.max(1, Number(enemy.level || 1)),
        id: String(enemy.id || ''),
        name: String(enemy.name || enemy.id || '不明'),
       }))
      : [],
    }));
  }

  function loadBattleHistory() {
   return normalizeBattleHistory(loadDiscoveryMap(BATTLE_HISTORY_STORAGE_KEY));
  }

  function saveBattleHistory(history) {
   saveDiscoveryMap(BATTLE_HISTORY_STORAGE_KEY, normalizeBattleHistory(history));
  }

  function formatDuration(ms) {
   const totalSeconds = Math.max(0, Math.floor(Number(ms || 0) / 1000));
   const minutes = Math.floor(totalSeconds / 60);
   const seconds = totalSeconds % 60;
   if (minutes <= 0) return `${seconds}秒`;
   return `${minutes}分${String(seconds).padStart(2, '0')}秒`;
  }

  function getPassiveDisplayNameById(passiveId) {
   const option = currentPassiveChoices.find(passive => passive.id === passiveId) || getPassiveOptions().find(passive => passive.id === passiveId);
   return option ? option.name : passiveId;
  }

  function getDeckSnapshotEntries(deckSnapshot) {
   return Object.entries(deckSnapshot || {})
    .filter(([, count]) => Number(count) > 0)
    .sort(([a], [b]) => a.localeCompare(b, 'ja'));
  }

  function getDeckSummaryText(deckSnapshot, limit = 5) {
   const entries = getDeckSnapshotEntries(deckSnapshot);
   if (entries.length === 0) return 'なし';
   const visible = entries.slice(0, limit).map(([name, count]) => `${name}×${count}`);
   const rest = entries.length - visible.length;
   return `${visible.join('')}${rest > 0 ? ` 他${rest}種類` : ''}`;
  }

  function recordBattleHistoryEntry(result) {
   if (!battleResultStats || !battleResultStats.endedAt) return;

   const runKey = runStartedAt || battleResultStats.startedAt || Date.now();
   const pet = getPetById(currentRunPetId || selectedPetId || 'none');
   const passiveIds = Array.from(new Set(currentRunPassiveIds || []));
   const history = loadBattleHistory();
   const existingIndex = history.findIndex(item => Number(item.runStartedAt || 0) === Number(runKey));
   const previous = existingIndex >= 0 ? history[existingIndex] : null;
   const reachedLevel = Math.max(
    Number(previous?.reachedLevel || 0),
    Number(enemyLevel || 1),
    Number(battleResultStats.level || 1),
   );
   const runResult = result === 'lose'
    ? 'lose'
    : reachedLevel >= 20
     ? 'win'
     : 'progress';
   const entry = {
    id: previous?.id || `run-${runKey}`,
    runStartedAt: runKey,
    recordedAt: Date.now(),
    result: runResult,
    depth: currentDepth,
    reachedLevel,
    playTimeMs: Math.max(0, Date.now() - runKey),
    cardsUsed: Math.max(Number(previous?.cardsUsed || 0), Number(battleResultStats.cardsUsed || 0)),
    cardPlayCounts: structuredClone(currentRunCardPlayCounts || battleResultStats.cardPlayCounts || previous?.cardPlayCounts || {}),
    damageDealt: Math.max(Number(previous?.damageDealt || 0), Number(battleResultStats.damageDealt || 0)),
    damageTaken: Math.max(Number(previous?.damageTaken || 0), Number(battleResultStats.damageTaken || 0)),
    remainingHp: battleResultStats.remainingHp || 0,
    petId: pet?.id || currentRunPetId || selectedPetId || 'none',
    petName: pet?.name || 'なし',
    deck: structuredClone(currentRunDeckSnapshot || savedDeckCustomize || {}),
    passives: passiveIds.map(id => ({ id, name: getPassiveDisplayNameById(id) })),
    enemies: Array.isArray(currentRunEnemyHistory) ? structuredClone(currentRunEnemyHistory) : [],
    events: Array.isArray(currentRunRandomEvents) ? structuredClone(currentRunRandomEvents) : [],
   };

   if (existingIndex >= 0) {
    history.splice(existingIndex, 1);
   }

   history.unshift(entry);
   saveBattleHistory(history.slice(0, MAX_BATTLE_HISTORY_COUNT));

   if (window.DeckFirebaseRanking && typeof window.DeckFirebaseRanking.submitBattleResult === 'function') {
    window.DeckFirebaseRanking.submitBattleResult(entry).catch(error => {
     console.warn('Firebase ranking submit failed', error);
    });
   }
  }

