  function showAchievementUnlockPopup(definition) {
   if (!definition) return;

   let layer = document.getElementById('achievement-toast-layer');
   if (!layer) {
    layer = document.createElement('div');
    layer.id = 'achievement-toast-layer';
    document.body.appendChild(layer);
   }

   const toast = document.createElement('div');
   toast.className = `achievement-unlock-toast ${definition.hidden ? 'secret' : ''}`;
   toast.innerHTML = `
    <div class="achievement-unlock-icon">${definition.icon || '🏆'}</div>
    <div class="achievement-unlock-body">
     <div class="achievement-unlock-kicker">実績解除</div>
     <div class="achievement-unlock-title">${escapeHtml(definition.name)}</div>
     <div class="achievement-unlock-desc">${escapeHtml(definition.description)}</div>
    </div>
   `;
   layer.appendChild(toast);

   playSound('success');
   setTimeout(() => toast.classList.add('show'), 20);
   setTimeout(() => {
    toast.classList.remove('show');
    setTimeout(() => toast.remove(), 420);
   }, 3600);
  }

  function evaluateAchievements({ silent = false } = {}) {
   const stats = loadAchievementStats();
   const achievements = loadAchievements();
   let changed = false;
   const unlockedNow = [];

   getAchievementDefinitions().forEach(definition => {
    const current = getAchievementProgress(definition, stats);
    const target = getAchievementTarget(definition);
    if (!achievements[definition.id] && current >= target) {
     achievements[definition.id] = { unlockedAt: Date.now() };
     changed = true;
     unlockedNow.push(definition);
     addLog(`実績解除：${definition.name}`);
    }
   });

   if (changed) saveAchievements(achievements);
   if (!silent) unlockedNow.forEach(definition => showAchievementUnlockPopup(definition));
  }

  function updateAchievementStats(mutator, options = {}) {
   const stats = loadAchievementStats();
   mutator(stats);
   saveAchievementStats(stats);
   evaluateAchievements(options);
  }

  function recordAchievementStat(key, amount = 1) {
   updateAchievementStats(stats => {
    stats[key] = Math.max(0, Number(stats[key] || 0) + Number(amount || 0));
   });
  }

  function recordAchievementMax(key, value) {
   updateAchievementStats(stats => {
    stats[key] = Math.max(Number(stats[key] || 0), Number(value || 0));
   });
  }

  function recordBattleStartAchievement(level) {
   updateAchievementStats(stats => {
    stats.totalBattles += 1;
    stats.highestLevel = Math.max(stats.highestLevel || 0, Number(level || 0));
   });
  }

  function recordCardUseAchievement() {
   updateAchievementStats(stats => {
    stats.totalCardsUsed += 1;
   });
  }

  function recordBattleEndAchievement(result) {
   if (!battleResultStats) return;

   updateAchievementStats(stats => {
    if (result === 'win') {
     stats.totalWins += 1;
     if (Number(battleResultStats.damageTaken || 0) <= 0) {
      stats.noDamageWins += 1;
     }
     if (Number(battleResultStats.remainingHp || 0) === 1) {
      stats.hpOneWins += 1;
     }
     if (Number(battleResultStats.level || 0) >= 20) {
      stats.level20Wins += 1;
      const depth = normalizeDepth(battleResultStats.depth || currentDepth);
      if (depth === 1) stats.depth1Clears += 1;
      if (depth === 2) stats.depth2Clears += 1;
      if (depth === 3) stats.depth3Clears += 1;
     }
    } else {
     stats.totalLosses += 1;
    }

    stats.totalDamageDealt += Math.max(0, Number(battleResultStats.damageDealt || 0));
    stats.totalDamageTaken += Math.max(0, Number(battleResultStats.damageTaken || 0));
    stats.highestLevel = Math.max(stats.highestLevel || 0, Number(battleResultStats.level || 0));
   });
  }

