function getEffectiveCardCooldownSeconds(card, options = {}) {
 const baseCooldown = getCardCooldownSeconds(card);
 const hasTemporaryReduce = player && player.nextCardCooldownReduceUses > 0;
 const temporaryReduceAmount = hasTemporaryReduce ? (player.nextCardCooldownReduceAmount || 0) : 0;
 // 加速自身や硬直1秒以下のカードには加速効果を乗せない。
 // その場合は「次の2枚」のカウントも消費しない。
 const canApplyTemporaryReduce = hasTemporaryReduce
  && card?.type !== 'cooldown-boost'
  && baseCooldown > 1;
 const tempReduce = canApplyTemporaryReduce ? temporaryReduceAmount : 0;
 const totalReduce = (playerPassives.cooldownReduce || 0) + tempReduce;
 const burnPenalty = player && player.burn && Number(player.burnTurns || 0) > 0 ? 0.5 : 0;
 const cooldown = Math.max(0.5, roundToTenthSecond(baseCooldown - totalReduce + burnPenalty));

 if (options.consume && tempReduce > 0) {
  player.nextCardCooldownReduceUses = Math.max(0, (player.nextCardCooldownReduceUses || 0) - 1);
  if (player.nextCardCooldownReduceUses <= 0) {
   player.nextCardCooldownReduceAmount = 0;
  }
 }

 return cooldown;
}

function getCardCooldownText(card) {
 return `硬直 ${getCardCooldownSeconds(card).toFixed(1).replace('.0', '')}秒`;
}

function getEffectiveCardCooldownText(card) {
  return `硬直 ${getEffectiveCardCooldownSeconds(card).toFixed(1).replace('.0', '')}秒`;
}


