function getEffectiveCardValue(card) {
 if (!card) return 0;

 let value = Number(card.value || 0);
 if (!Number.isFinite(value)) value = 0;

 

  if (isAttackCardType(card.type)) {
   value += playerPassives.attack;
   if (player && Array.isArray(player.hand) && player.hand.length <= 2) {
    value += Math.max(0, Number(playerPassives.lowHandAttackBonus || 0));
   }
   if (player && Number(player.tempAttackBuffTurns || 0) > 0) {
    value += Math.max(0, Number(player.tempAttackBuffValue || 0));
   }

  if (player && player.petAttackBoost) {
   value += player.petAttackBoost;
  }

  if (player && player.enhanceNextAttack) {
   value *= 2;
  }

  if (player && Number(player.bloodAwakenAttackBoostUses || 0) > 0) {
   value *= 2;
  }

  if (playerPassives.packAssaultReady) {
   value = Math.round(value * 1.5);
  }

  return value;
 }

 if (isDefenseCardType(card.type)) {
  value += playerPassives.defense;

  if (player && player.enhanceNextDefense) {
   value *= 2;
  }

  return value;
 }

 if (card.type === 'heal' || card.type === 'rare-heal') {
  return value + playerPassives.healBonus;
 }

 return value;
}

function shouldShowPassiveChoice(nextLevel) {
 // Lv1戦闘前は startBattle() で表示。
 // Lv4/8/12/16撃破後 = 次レベルが 5/9/13/17 のとき表示。
 return [5, 9, 13, 17].includes(nextLevel);
}

function isRarePassiveSelectionLevel(nextLevel) {
 // Lv12撃破後・Lv16撃破後はレアパッシブのみ。
 return nextLevel === 13 || nextLevel === 17;
}


