function isEnemyDamageAction(action) {
 return ['attack', 'enemy-paralyze', 'enemy-freeze', 'enemy-burn', 'enemy-poison', 'enemy-bomb'].includes(action?.type);
}

function applyDangerSenseForNextAction() {
 if (!player || !cpu || !cpu.nextAction || gameOver) return;

 const blockGain = Math.max(0, Number(playerPassives.dangerSenseBlock || 0));
 if (blockGain <= 0 || !isEnemyDamageAction(cpu.nextAction)) return;
 if (cpu.nextAction.dangerSenseApplied) return;

 cpu.nextAction.dangerSenseApplied = true;
 player.block += blockGain;
 recordAchievementMax('maxBlock', player.block || 0);
 addLog(`危険察知：敵の攻撃を察知して防御+${blockGain}`);
 showDamagePopup('player-hp-change', `防御+${blockGain}`);
 triggerCardVisualEffect('.player-img', 'guard');
 playSound('guard');
}

function rebalanceLateEnemyActionPool(cpuPool) {
 if (!Array.isArray(cpuPool)) return cpuPool;

 const enemyId = getCurrentEnemyCatalogEntry()?.id || currentEnemyId || '';
 const balancedPool = cpuPool.map(card => ({ ...card }));

 const adjustByValue = (type, from, to) => {
  const target = balancedPool.find(card => card.type === type && Number(card.value || 0) === from);
  if (!target) return;
  target.value = to;
  if (type === 'attack') target.text = `${to}ダメージ`;
  if (type === 'enemy-paralyze') target.text = `${to}ダメージ / 麻痺`;
  if (type === 'enemy-freeze') target.text = `${to}ダメージ / 凍結`;
 };

 if (enemyLevel >= 17 && enemyLevel <= 19) {
  if (enemyId === 'abyss_reaper') {
   adjustByValue('attack', 19, 16);
   adjustByValue('attack', 22, 19);
   adjustByValue('attack', 25, 22);
   adjustByValue('attack', 29, 25);
   adjustByValue('enemy-paralyze', 12, 10);
   adjustByValue('enemy-paralyze', 15, 12);
   if (enemyLevel >= 18) balancedPool.push(createEnemyDefenseAction('深淵の間合い', 16));
   if (enemyLevel >= 19) balancedPool.push(createEnemyDefenseAction('刈り取りの構え', 18));
  } else if (enemyId === 'shadow_knight') {
   adjustByValue('attack', 18, 15);
   adjustByValue('attack', 21, 18);
   adjustByValue('attack', 24, 21);
   adjustByValue('attack', 28, 24);
   if (enemyLevel >= 18) balancedPool.push(createEnemyDefenseAction('影の受け流し', 17));
  } else if (enemyId === 'obsidian_warden') {
   adjustByValue('attack', 18, 16);
   adjustByValue('attack', 20, 18);
   adjustByValue('attack', 22, 20);
   adjustByValue('attack', 25, 22);
  }
 }

 if (enemyLevel >= 20 && enemyId === 'void_knight') {
  const isSecondPhase = Boolean(cpu && cpu.phase === 2);
  if (isSecondPhase) {
   adjustByValue('attack', 26, 24);
   adjustByValue('enemy-paralyze', 18, 16);
   adjustByValue('attack', 40, 34);
   balancedPool.push(createEnemyDefenseAction('虚無の防壁', 22));
  } else {
   adjustByValue('attack', 24, 22);
  }
 }

 return balancedPool;
}

function isPlayerStatusGuardActive() {
 return Boolean(player && Number(player.statusGuardTurns || 0) > 0);
}

function consumePlayerStatusGuard(statusName) {
 if (!isPlayerStatusGuardActive()) return false;
 triggerCardVisualEffect('.player-img', 'guard');
 showDamagePopup('player-hp-change', '無効');
 addLog(`ステータスガード：${statusName}を無効化`);
 playSound('guard');
 return true;
}

function tryApplyEnemyParalysis(turns = 3) {
 if (isEnemyParalysisImmune()) {
  triggerCardVisualEffect('.cpu-img', 'guard');
  playSound('guard');
  return false;
 }

 cpu.paralysis = (cpu.paralysis || 0) + Math.max(1, Number(turns || 3));
 triggerParalysisEffect('.cpu-img');
 playSound('paralysis');
 return true;
}

function tryApplyEnemyFreeze(turns = 1, chance = 1) {
 if (isEnemyFreezeImmune()) {
  triggerCardVisualEffect('.cpu-img', 'guard');
  playSound('guard');
  return false;
 }
 const actualChance = Math.max(0, Math.min(1, Number(chance || 0) * getEnemyFreezeApplyChanceMultiplier()));
 if (Math.random() > actualChance) return false;
 if (enemyHasPassive('freeze_resist') && Math.random() < 0.5) {
  triggerCardVisualEffect('.cpu-img', 'guard');
  playSound('guard');
  return false;
 }
 cpu.freeze = Math.max(Number(cpu.freeze || 0), Math.max(1, Number(turns || 1)));
 recordAchievementStat('freezeApplications');
 triggerFreezeEffect('.cpu-img');
 playSound('freeze');
 return true;
}

  function getEnemyImageSrc() {
   const displayLevel = getDisplayEnemyLevel();
   const enemyId = getCurrentEnemyCatalogEntry()?.id || currentEnemyId;
   if (enemyId === 'obsidian_overlord') return 'assets/enemies/obsidian_overlord.png';
   if (enemyId === 'abyss_beast_king') return 'assets/enemies/abyss_beast_king.png';
   if (displayLevel >= 20 && isVoidBossEnemyId(enemyId)) {
    return cpu && cpu.phase === 2 ? GAME_IMAGES.void_phase2 : GAME_IMAGES.img_009;
   }

   return getCurrentEnemyCatalogEntry()?.image || GAME_IMAGES.img_014;
  }

