function filterCurrentBattleExcludedCards(cards, excludeCardId = null, options = {}) {
 const excludedTypes = new Set(player?.excludedBattleCardTypes || []);
 const excludedNames = new Set(player?.excludedBattleCardNames || []);
 if (!Array.isArray(cards)) return cards;
 const filtered = (!excludedTypes.size && !excludedNames.size)
  ? cards
  : cards.filter(card => card.id === excludeCardId || (!excludedTypes.has(card.type) && !excludedNames.has(card.name)));
 return options.includeExhausted ? filterCurrentBattleExhaustedCards(filtered) : filtered;
}

function discardPlayedCardForCurrentBattle(cardOrId) {
 if (!player || !cardOrId) return;
 const card = typeof cardOrId === 'object' ? cardOrId : (player.hand || []).find(item => item.id === cardOrId);
 const cardId = typeof cardOrId === 'object' ? cardOrId.id : cardOrId;
 const cardName = card?.name || null;

 if (cardName) {
  if (!player.exhaustedBattleCardNames || typeof player.exhaustedBattleCardNames !== 'object') {
   player.exhaustedBattleCardNames = {};
  }
  player.exhaustedBattleCardNames[cardName] = Math.max(0, Number(player.exhaustedBattleCardNames[cardName] || 0)) + 1;
 }

 player.hand = Array.isArray(player.hand) ? player.hand.filter(item => item.id !== cardId) : [];
 actionQueue = getActionQueue().filter(action => !(action && action.type === 'card' && action.cardId === cardId));
 deckCount = playerDeck.length;
}

function excludeCardTypeForCurrentBattle(type, excludeCardId = null) {
 if (!player || !type) return;
 if (!Array.isArray(player.excludedBattleCardTypes)) player.excludedBattleCardTypes = [];
 if (!player.excludedBattleCardTypes.includes(type)) player.excludedBattleCardTypes.push(type);
 playerDeck = filterCurrentBattleExcludedCards(playerDeck, excludeCardId);
 player.hand = filterCurrentBattleExcludedCards(player.hand, excludeCardId);
 deckCount = playerDeck.length;
}

function excludeCardNameForCurrentBattle(cardName, excludeCardId = null) {
 if (!player || !cardName) return;
 if (!Array.isArray(player.excludedBattleCardNames)) player.excludedBattleCardNames = [];
 if (!player.excludedBattleCardNames.includes(cardName)) player.excludedBattleCardNames.push(cardName);
 playerDeck = filterCurrentBattleExcludedCards(playerDeck, excludeCardId);
 player.hand = filterCurrentBattleExcludedCards(player.hand, excludeCardId);
 deckCount = playerDeck.length;
}

function drawPlayerHandToSize(targetSize) {
 if (!player || !Array.isArray(player.hand)) return [];
 const target = Math.max(0, Math.floor(Number(targetSize || 0)));
 const missing = Math.max(0, target - player.hand.length);
 return drawCardsToPlayerHand(missing);
}

function addTemporaryRandomCardToHand() {
 if (!player || !Array.isArray(player.hand)) return null;
 const card = createTemporaryBattleCard(pickWeightedRandomCard({ includeCurse: false }));
 player.hand.push(card);
 recordCardDiscovery(card.name);
 triggerCardResultReveal([card], '一時カード追加', '使用後破棄', { delay: 760, temporary: true });
 return card;
}

function isEnemyPreparingAttack() {
 if (!cpu || !cpu.nextAction) return false;
 return ['attack', 'enemy-paralyze', 'enemy-freeze', 'enemy-burn', 'enemy-poison', 'enemy-bomb'].includes(cpu.nextAction.type);
}

function discardRandomPlayerHandCard(options = {}) {
 if (!player || !Array.isArray(player.hand) || player.hand.length <= 0) return null;

 const excludeIds = new Set(Array.isArray(options.excludeIds) ? options.excludeIds : []);
 const candidates = player.hand
  .map((card, index) => ({ card, index }))
  .filter(item => !excludeIds.has(item.card?.id));

 if (candidates.length <= 0) return null;

 const selected = candidates[Math.floor(Math.random() * candidates.length)];
 const [discarded] = player.hand.splice(selected.index, 1);
 return discarded || null;
}



function isPlayerFrozen() {
 return Boolean(player && player.frozen === true);
}

function getFreezeRemainingClicks() {
 if (!isPlayerFrozen()) return 0;
 const required = Number(player.freezeRequiredClicks || 10);
 const count = Number(player.freezeClickCount || 0);
 return Math.max(0, required - count);
}

function clearPlayerFreeze() {
 if (player) {
  player.frozen = false;
  player.freezeTimer = 0;
  player.freezeClickCount = 0;
  player.freezeRequiredClicks = 10;
 }

 const cardsElement = document.getElementById('cards');
 if (cardsElement) {
  cardsElement.classList.remove('frozen-hand');
 }

 const playerImage = document.querySelector('.player-img');
 if (playerImage) {
  playerImage.classList.remove('frozen-status-effect');
 }
}

function updatePlayerFreezeVisual() {
 const frozen = isPlayerFrozen();

 const cardsElement = document.getElementById('cards');
 if (cardsElement) {
  cardsElement.classList.toggle('frozen-hand', frozen);
  if (frozen) {
   cardsElement.dataset.freezeText = `❄ 凍結 ❄ あと${getFreezeRemainingClicks()}回クリックで解除`;
  } else {
   delete cardsElement.dataset.freezeText;
  }
 }

 const playerImage = document.querySelector('.player-img');
 if (playerImage) {
  playerImage.classList.toggle('frozen-status-effect', frozen);
 }
}

function stopPlayerStatusTimer() {
 if (playerStatusInterval) {
  clearInterval(playerStatusInterval);
  playerStatusInterval = null;
 }
}

function startPlayerStatusTimer() {
 // 凍結は時間経過では解除しない。戦闘画面のクリックで解除する。
 // 既存呼び出し互換のため関数は残すが、タイマーは開始しない。
 stopPlayerStatusTimer();
}

function applyPlayerFreeze(requiredClicks = 10) {
 if (!player) return;
 if (consumePlayerStatusGuard('凍結')) return;

 player.frozen = true;
 player.freezeTimer = 0;
 player.freezeRequiredClicks = requiredClicks;
 player.freezeClickCount = 0;

 updatePlayerFreezeVisual();
 addLog(`凍結：戦闘画面を${requiredClicks}回クリックで解除`);
 render();
}

let lastPlayerFreezeBreakInputAt = 0;
let lastPlayerFreezeBreakInputX = null;
let lastPlayerFreezeBreakInputY = null;

function stopPlayerFreezeBreakEvent(event) {
 if (!event) return;
 event.preventDefault();
 event.stopPropagation();
 if (typeof event.stopImmediatePropagation === 'function') {
  event.stopImmediatePropagation();
 }
}

function isRecentPlayerFreezeBreakInput(event) {
 const now = Date.now();
 const clientX = Number(event?.clientX ?? NaN);
 const clientY = Number(event?.clientY ?? NaN);

 return now - lastPlayerFreezeBreakInputAt < 250
  && (Number.isNaN(clientX) || lastPlayerFreezeBreakInputX === null || Math.abs(clientX - lastPlayerFreezeBreakInputX) < 4)
  && (Number.isNaN(clientY) || lastPlayerFreezeBreakInputY === null || Math.abs(clientY - lastPlayerFreezeBreakInputY) < 4);
}

function shouldHandlePlayerFreezeBreakClick(event) {
 if (!isPlayerFrozen() || gameOver || currentScreen !== 'battle') return false;
 if (isRandomEventInputBlocked()) return false;
 if (bossRevivalInProgress || pendingPassiveChoice || pendingShopChoice) return false;
 if (event && typeof event.button === 'number' && event.button !== 0) return false;
 if (event && event.type === 'pointerdown' && event.isPrimary === false) return false;

 const target = event?.target;
 if (!target || typeof target.closest !== 'function') return false;

 return Boolean(target.closest('#battle-screen'));
}

function consumePlayerFreezeBreakClick(event) {
 if (!shouldHandlePlayerFreezeBreakClick(event)) return false;

 const now = Date.now();
 const clientX = Number(event?.clientX ?? NaN);
 const clientY = Number(event?.clientY ?? NaN);
 const isDuplicateClick = event?.type === 'click' && isRecentPlayerFreezeBreakInput(event);

 stopPlayerFreezeBreakEvent(event);

 if (isDuplicateClick) return true;

 lastPlayerFreezeBreakInputAt = now;
 lastPlayerFreezeBreakInputX = Number.isNaN(clientX) ? null : clientX;
 lastPlayerFreezeBreakInputY = Number.isNaN(clientY) ? null : clientY;

 if (player) {
  player.freezeClickCount = Math.min(
   Number(player.freezeRequiredClicks || 10),
   Number(player.freezeClickCount || 0) + 1
  );
 }

 const remaining = getFreezeRemainingClicks();
 if (remaining <= 0) {
  clearPlayerFreeze();
  addLog('凍結解除');
  playSound('iceBreak');
 } else {
  playSound('iceTick');
 }

 updatePlayerFreezeVisual();
 render();
 return true;
}

function handlePlayerFreezeBreakGlobalInput(event) {
 if (isRandomEventInputBlocked()) return;

 if (event?.type === 'click' && isRecentPlayerFreezeBreakInput(event)) {
  stopPlayerFreezeBreakEvent(event);
  return;
 }

 consumePlayerFreezeBreakClick(event);
}

if (typeof document !== 'undefined' && !document.__deckPlayerFreezeBreakInstalled) {
 document.__deckPlayerFreezeBreakInstalled = true;
 document.addEventListener('pointerdown', handlePlayerFreezeBreakGlobalInput, true);
 document.addEventListener('click', handlePlayerFreezeBreakGlobalInput, true);
}

function handleHandAreaClick(event) {
 if (isRandomEventInputBlocked()) {
  event?.preventDefault?.();
  event?.stopPropagation?.();
  return;
 }

 if (isPlayerFrozen()) {
  consumePlayerFreezeBreakClick(event);
  return;
 }

 const cardButton = event?.target?.closest?.('.card[data-card-id]');
 if (!cardButton) return;

 const cardId = cardButton.dataset.cardId;
 if (!cardId) return;

 if (suppressQueuedCardClickId === cardId && Date.now() < suppressQueuedCardClickUntil) {
  event.preventDefault();
  event.stopPropagation();
  return;
 }

 event.preventDefault();
 event.stopPropagation();
 playPlayerCard(cardId);
}

