  function getEnemyMaxHp() {
 if (enemyLevel >= 20) {
  if (isVoidBossEnemyId()) return scaleEnemyNumberByDepth(cpu && cpu.phase === 2 ? 260 : 430, 'enemyHpMultiplier');
  if (currentEnemyId === 'obsidian_overlord') return scaleEnemyNumberByDepth(680, 'enemyHpMultiplier');
  if (currentEnemyId === 'abyss_beast_king') return scaleEnemyNumberByDepth(700, 'enemyHpMultiplier');
  return scaleEnemyNumberByDepth(430, 'enemyHpMultiplier');
 }

 const hpCurve = [
  { level: 1, hp: 30 },
  { level: 5, hp: 70 },
  { level: 10, hp: 140 },
  { level: 15, hp: 220 },
  { level: 19, hp: 300 },
 ];

 for (let i = 0; i < hpCurve.length - 1; i += 1) {
  const from = hpCurve[i];
  const to = hpCurve[i + 1];

  if (enemyLevel >= from.level && enemyLevel <= to.level) {
   const progress = (enemyLevel - from.level) / (to.level - from.level);
   return scaleEnemyNumberByDepth(Math.round(from.hp + (to.hp - from.hp) * progress), 'enemyHpMultiplier');
  }
 }

 return scaleEnemyNumberByDepth(hpCurve[hpCurve.length - 1].hp, 'enemyHpMultiplier');
}

  
let lastUiSelectSoundAt = 0;

function playUiSelectSound() {
 try {
  const now = Date.now();
  if (now - lastUiSelectSoundAt < 80) return;
  lastUiSelectSoundAt = now;
  playSound('success');
 } catch (e) {
  console.warn(e);
 }
}

function installGlobalButtonSe() {
 if (window.__voidCardGlobalButtonSeInstalled) return;
 window.__voidCardGlobalButtonSeInstalled = true;
 document.addEventListener('click', event => {
  const button = event.target && event.target.closest ? event.target.closest('button') : null;
  if (!button || button.disabled || button.dataset.noSe === 'true') return;
  playUiSelectSound();
 }, true);
}

installGlobalButtonSe();

function playSound(type) {
   if (type === 'damage') {
    lastDamageMp3SoundAt = Date.now();
    playUploadedSound('damage', 0.13);
    return;
   }

   if (type === 'guard') {
    playUploadedSound('defense', 0.07);
    return;
   }

   if (type === 'flame') {
    playUploadedSound('flame', 0.12);
    return;
   }

   if (type === 'paralysis' || type === 'electricity') {
    playUploadedSound('electricity', 0.14);
    return;
   }

   if (type === 'victory' || type === 'won') {
    playUploadedSound('won', 0.15);
    return;
   }

   if (['attack', 'reflect', 'flame', 'paralysis', 'electricity'].includes(type) && Date.now() - lastDamageMp3SoundAt < 180) {
    // ダメージ発生直後はdamage.mp3だけを鳴らし、発振音や属性SEとの二重再生を防ぐ。
    return;
   }

   const AudioContext = window.AudioContext || window.webkitAudioContext;
   if (!AudioContext) return;

   const audio = new AudioContext();
   const oscillator = audio.createOscillator();
   const gain = audio.createGain();

   oscillator.connect(gain);
   gain.connect(audio.destination);

   const now = audio.currentTime;

   if (type === 'iceTick') {
    // 凍結解除クリック中：小さく軽い「ピキッ」音。未定義SEの大音量再生を防ぐ。
    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(1400, now);
    oscillator.frequency.exponentialRampToValueAtTime(1850, now + 0.035);
    gain.gain.setValueAtTime(0.018, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.055);
    oscillator.start(now);
    oscillator.stop(now + 0.06);
    return;
   }

   if (type === 'iceBreak') {
    // 凍結解除専用：音量を大きく下げた、短く軽い氷割れ音
    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(1650, now);
    oscillator.frequency.exponentialRampToValueAtTime(2300, now + 0.035);
    oscillator.frequency.exponentialRampToValueAtTime(1500, now + 0.075);
    gain.gain.setValueAtTime(0.026, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.09);
    oscillator.start(now);
    oscillator.stop(now + 0.10);
    return;
   }

   if (type === 'attack') {
    oscillator.type = 'sawtooth';
    oscillator.frequency.setValueAtTime(260, now);
    oscillator.frequency.exponentialRampToValueAtTime(90, now + 0.12);
    gain.gain.setValueAtTime(0.12, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.14);
   }

   if (type === 'defense') {
    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(420, now);
    oscillator.frequency.exponentialRampToValueAtTime(760, now + 0.12);
    gain.gain.setValueAtTime(0.04, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);
   }

   if (type === 'damage') {
    oscillator.type = 'square';
    oscillator.frequency.setValueAtTime(160, now);
    oscillator.frequency.exponentialRampToValueAtTime(70, now + 0.10);
    gain.gain.setValueAtTime(0.10, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
   }

   if (type === 'guard') {
    oscillator.type = 'triangle';
    oscillator.frequency.setValueAtTime(2200, now);
    oscillator.frequency.exponentialRampToValueAtTime(1800, now + 0.05);
    gain.gain.setValueAtTime(0.05, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.06);
   }

   if (type === 'reload') {
    oscillator.type = 'triangle';
    oscillator.frequency.setValueAtTime(240, now);
    oscillator.frequency.exponentialRampToValueAtTime(520, now + 0.20);
    gain.gain.setValueAtTime(0.08, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.22);
   }

   if (type === 'success') {
    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(520, now);
    oscillator.frequency.exponentialRampToValueAtTime(880, now + 0.20);
    gain.gain.setValueAtTime(0.10, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.24);
   }

   if (type === 'paralysis') {
    oscillator.type = 'square';
    oscillator.frequency.setValueAtTime(900, now);
    oscillator.frequency.exponentialRampToValueAtTime(220, now + 0.18);
    gain.gain.setValueAtTime(0.08, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.20);
   }

   if (type === 'freeze') {
    oscillator.type = 'triangle';
    oscillator.frequency.setValueAtTime(1200, now);
    oscillator.frequency.exponentialRampToValueAtTime(400, now + 0.25);
    gain.gain.setValueAtTime(0.07, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.28);
   }

   if (type === 'poison') {
    oscillator.type = 'triangle';

    oscillator.frequency.setValueAtTime(180, now);
    oscillator.frequency.exponentialRampToValueAtTime(95, now + 0.22);

    gain.gain.setValueAtTime(0.025, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.26);
   }

   if (type === 'miss') {
    oscillator.type = 'sine';
    oscillator.frequency.setValueAtTime(180, now);
    oscillator.frequency.exponentialRampToValueAtTime(120, now + 0.10);
    gain.gain.setValueAtTime(0.035, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
   }

   if (type === 'reflect') {
    oscillator.type = 'triangle';
    oscillator.frequency.setValueAtTime(520, now);
    oscillator.frequency.exponentialRampToValueAtTime(980, now + 0.08);
    oscillator.frequency.exponentialRampToValueAtTime(260, now + 0.22);
    gain.gain.setValueAtTime(0.085, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.28);
   }

   if (type === 'critical') {
    oscillator.type = 'square';
    oscillator.frequency.setValueAtTime(620, now);
    oscillator.frequency.exponentialRampToValueAtTime(1180, now + 0.06);
    oscillator.frequency.exponentialRampToValueAtTime(520, now + 0.18);
    gain.gain.setValueAtTime(0.13, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.24);
   }


   if (type === 'voidRevivalStart') {
    oscillator.type = 'sawtooth';
    oscillator.frequency.setValueAtTime(95, now);
    oscillator.frequency.exponentialRampToValueAtTime(52, now + 0.45);
    gain.gain.setValueAtTime(0.13, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.55);
    oscillator.start(now);
    oscillator.stop(now + 0.58);
    return;
   }

   if (type === 'voidRevivalPulse') {
    oscillator.type = 'triangle';
    oscillator.frequency.setValueAtTime(70, now);
    oscillator.frequency.exponentialRampToValueAtTime(135, now + 0.22);
    oscillator.frequency.exponentialRampToValueAtTime(58, now + 0.48);
    gain.gain.setValueAtTime(0.055, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.52);
    oscillator.start(now);
    oscillator.stop(now + 0.55);
    return;
   }

   if (type === 'voidRevivalAwaken') {
    oscillator.type = 'sawtooth';
    oscillator.frequency.setValueAtTime(120, now);
    oscillator.frequency.exponentialRampToValueAtTime(360, now + 0.18);
    oscillator.frequency.exponentialRampToValueAtTime(90, now + 0.52);
    gain.gain.setValueAtTime(0.14, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.62);
    oscillator.start(now);
    oscillator.stop(now + 0.65);
    return;
   }

   if (!['attack', 'defense', 'damage', 'guard', 'reload', 'success', 'paralysis', 'freeze', 'poison', 'miss', 'reflect', 'critical'].includes(type)) {
    // 未定義の効果音でデフォルト音量の発振音が鳴らないようにする
    return;
   }

   oscillator.start(now);
   oscillator.stop(now + 0.25);
  }

  function addLog(text) {
   logs.unshift(text);
   logs = logs.slice(0, 10);
  }

  function resetBattleResultStats() {
   battleResultStats = {
    level: enemyLevel,
    enemyName: getEnemyName(),
    depth: currentDepth,
    startedAt: Date.now(),
    endedAt: null,
    result: null,
    cardsUsed: 0,
    cardPlayCounts: {},
    damageDealt: 0,
    damageTaken: 0,
    remainingHp: 0,
   };
  }

  function finalizeBattleResult(result) {
   if (!battleResultStats) {
    resetBattleResultStats();
   }

   if (battleResultStats.endedAt) return;
   clearActionQueue();

   if (player && Array.isArray(player.hand)) {
    player.hand = player.hand.filter(card => !card.temporaryBattleCard);
   }
   if (Array.isArray(playerDeck)) {
    playerDeck = playerDeck.filter(card => !card.temporaryBattleCard);
    deckCount = playerDeck.length;
   }

   if (result === 'win' && playerPassives.maxHpOnBattleWin > 0) {
    const gain = Math.max(0, Number(playerPassives.maxHpOnBattleWin || 0));
    playerPassives.maxHp += gain;
    if (player) player.hp = Math.min(getPlayerMaxHp(), Number(player.hp || 0) + gain);
    addLog(`応急処置：最大HP+${gain}`);
   }

   battleResultStats.endedAt = Date.now();
   battleResultStats.result = result;
   battleResultStats.remainingHp = player ? Math.max(0, player.hp) : 0;
   battleResultStats.level = enemyLevel;
   battleResultStats.enemyName = getEnemyName();
   battleResultStats.depth = currentDepth;
   if (result === 'win' && enemyLevel >= 20) {
    markDepthCleared(currentDepth);
   }
   if (result === 'win' && enemyLevel >= 20) {
    handleRunEndRelicReward('clear');
   } else if (result === 'win') {
    handleBattleVictoryRelicReward();
   } else {
    lastRelicReward = null;
   }
   recordBattleEndAchievement(result);
   recordEnemyBattleResult(result);
   recordBattleHistoryEntry(result);
  }

  function getRelicRewardHtml(reward = lastRelicReward) {
   if (!reward || !reward.relicId) return '';
   return `
    <div class="relic-reward-result">
     <div class="relic-reward-kicker">遺物発見</div>
     <div class="relic-reward-name">${escapeHtml(reward.name || '')}</div>
     <div class="relic-reward-effect"><span>効果</span><strong>${escapeHtml(reward.effect || '')}</strong></div>
    </div>
   `;
  }

  function getRelicRewardModalHtml(reward = lastRelicReward) {
   if (!reward || !reward.relicId) return '';
   const relic = getRelicById(reward.relicId);
   const icon = relic?.icon || '◆';
   return `
    <div class="relic-reward-modal-kicker">遺物発見！</div>
    <div class="relic-reward-modal-icon">${escapeHtml(icon)}</div>
    <div class="relic-reward-modal-name">${escapeHtml(reward.name || relic?.name || '')}</div>
    <div class="relic-reward-modal-effect">
     <span>効果</span>
     <strong>${escapeHtml(reward.effect || relic?.effect || '')}</strong>
    </div>
   `;
  }

  function showRelicRewardModal(reward = lastRelicReward) {
   if (!reward || !reward.relicId) return;
   const modal = document.getElementById('relic-reward-modal');
   const content = document.getElementById('relic-reward-modal-content');
   if (!modal || !content) return;

   content.innerHTML = getRelicRewardModalHtml(reward);
   modal.style.display = 'flex';
   playSound('success');
  }

  function closeRelicRewardModal(event) {
   if (event && event.target && event.currentTarget && event.target !== event.currentTarget) return;
   const modal = document.getElementById('relic-reward-modal');
   if (modal) modal.style.display = 'none';
  }

  function showPendingRelicRewardModalIfNeeded() {
   if (relicRewardModalShownForRun || !lastRelicReward || !lastRelicReward.relicId) return;
   if (!(gameOver || currentScreen === 'clear')) return;

   relicRewardModalShownForRun = true;
   setTimeout(() => showRelicRewardModal(lastRelicReward), 120);
  }

  function getBattleResultHtml() {
   if (!battleResultStats) return '';

   const elapsedMs = Math.max(0, (battleResultStats.endedAt || Date.now()) - battleResultStats.startedAt);
   const elapsedSeconds = Math.max(1, Math.ceil(elapsedMs / 1000));
   const resultLabel = battleResultStats.result === 'win' ? '勝利' : '敗北';

   return `
    <div class="battle-result-panel">
     <div class="battle-result-title">戦闘リザルト</div>
     <div class="battle-result-enemy">${battleResultStats.enemyName} Lv.${battleResultStats.level}：${resultLabel}</div>
     <div class="battle-result-grid">
      <div><span>深度</span><strong>${getDepthLabel(battleResultStats.depth || currentDepth)}</strong></div>
      <div><span>経過時間</span><strong>${elapsedSeconds}秒</strong></div>
      <div><span>使用カード</span><strong>${battleResultStats.cardsUsed}枚</strong></div>
      <div><span>与えたダメージ</span><strong>${battleResultStats.damageDealt}</strong></div>
      <div><span>受けたダメージ</span><strong>${battleResultStats.damageTaken}</strong></div>
      <div><span>残りHP</span><strong>${battleResultStats.remainingHp} / ${getPlayerMaxHp()}</strong></div>
     </div>
     ${getRelicRewardHtml()}
    </div>
   `;
  }

  function getChanceSuccessEffectMultiplier() {
   return playerPassives.rareTripleLuck ? 3 : 1;
  }

  function getPetEvolutionEffectMultiplier() {
 return 1;
}

  function rollCriticalDamage(damage) {
   const baseDamage = Math.max(0, Number(damage || 0));
   const criticalChance = CRITICAL_CHANCE + Math.max(0, Number(playerPassives.criticalChanceBonus || 0));
   const critical = baseDamage > 0 && Math.random() < criticalChance;
   return {
    damage: critical ? Math.ceil(baseDamage * (playerPassives.rareCriticalDouble ? 2 : CRITICAL_DAMAGE_MULTIPLIER)) : baseDamage,
    baseDamage,
    critical,
   };
  }

  function getDamagePopupText(result) {
   if (!result || !result.damage) return '0';
   return result.critical ? `CRITICAL! -${result.damage}` : `-${result.damage}`;
  }

  function getPlayerDamagePreviewValue(damage) {
   let preview = Math.max(0, Number(damage || 0));
   if (!Number.isFinite(preview)) preview = 0;

   if (playerPassives.rareBerserkHalfHp && player && player.hp <= Math.floor(getPlayerMaxHp() / 2)) {
    preview *= 2;
   }

   if (cpu && Number(cpu.freeze || 0) > 0) {
    const frozenBonus = Math.max(0, Number(playerPassives.frozenVulnerabilityDamageBonus || 0));
    if (frozenBonus > 0) {
     preview = Math.ceil(preview * (1 + frozenBonus));
    }
   }

   return preview;
  }

  function applyPlayerSelfDamage(amount, label = '自傷') {
   if (!player) return 0;
   const selfDamage = Math.max(0, Math.floor(Number(amount || 0)));
   if (selfDamage <= 0) return 0;

   player.hp = Math.max(0, Number(player.hp || 0) - selfDamage);
   showDamagePopup('player-hp-change', `-${selfDamage}`);
   triggerDamageShake('.player-img');

   if (playerPassives.bloodPrice) {
    player.block += 1;
    recordAchievementMax('maxBlock', player.block || 0);
    showDamagePopup('player-hp-change', '防御+1');
   }

   if (player.hp <= 0) {
    player.hp = 0;
    render();
    handleBattleDefeat(`${label}でHPが0になりました`);
   }

   return selfDamage;
  }

  function triggerCriticalEffect() {
   let overlay = document.getElementById('battle-effect-overlay');
   if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'battle-effect-overlay';
    document.body.appendChild(overlay);
   }

   const effect = document.createElement('div');
   effect.className = 'critical-hit-effect';
   effect.innerHTML = '<div class="critical-hit-slash"></div><div class="critical-hit-text">CRITICAL!</div><div class="critical-hit-sub">1.5x DAMAGE</div>';
   overlay.appendChild(effect);

   const burst = document.createElement('div');
   burst.className = 'critical-screen-burst';
   overlay.appendChild(burst);

   setTimeout(() => effect.remove(), 980);
   setTimeout(() => burst.remove(), 620);
  }

  function applyPlayerCardDamage(damage) {
   let finalDamage = Math.max(0, Number(damage || 0));
   if (!Number.isFinite(finalDamage)) finalDamage = 0;
   if (playerPassives.rareBerserkHalfHp && player && player.hp <= Math.floor(getPlayerMaxHp() / 2)) {
    finalDamage *= 2;
   }
   const criticalRoll = rollCriticalDamage(finalDamage);
   const result = applyDamage(cpu, criticalRoll.damage);
   result.critical = criticalRoll.critical && result.damage > 0;
   result.baseDamage = criticalRoll.baseDamage;
   result.criticalMultiplier = result.critical ? (playerPassives.rareCriticalDouble ? 2 : CRITICAL_DAMAGE_MULTIPLIER) : 1;

   if (result.critical) {
    triggerCriticalEffect();
    playSound('critical');
    recordAchievementStat('criticalHits');
   }

   if (result.damage > 0) {
    recordAchievementMax('highestSingleHit', result.damage);
    if (cpu && Number(cpu.freeze || 0) > 0) {
     recordAchievementStat('freezeHits');
     recordAchievementStat('freezeDamage', result.damage);
    }
   }

   return result;
  }

  function applyDamage(target, damage, options = {}) {
   if (target === cpu && cpu && cpu.invincible) {
    return { damage: 0, fullyBlocked: true };
   }

   const beforeHp = target.hp;
   let incomingDamage = Math.max(0, Number(damage || 0));
   if (!Number.isFinite(incomingDamage)) incomingDamage = 0;
   const lowHpReduction = target === player && player && incomingDamage > 0 && player.hp <= Math.floor(getPlayerMaxHp() * 0.3)
    ? Math.max(0, Number(playerPassives.lowHpDamageReduction || 0))
    : 0;
   const lowHpReductionApplied = lowHpReduction > 0;
   if (lowHpReductionApplied) {
    incomingDamage = Math.max(0, Math.ceil(incomingDamage * (1 - Math.min(0.9, lowHpReduction))));
   }
   const frozenVulnerabilityBonus = target === cpu && target && Number(target.freeze || 0) > 0
    ? Math.max(0, Number(playerPassives.frozenVulnerabilityDamageBonus || 0))
    : 0;
   const frozenVulnerabilityApplied = frozenVulnerabilityBonus > 0 && incomingDamage > 0;
   if (frozenVulnerabilityApplied) {
    incomingDamage = Math.ceil(incomingDamage * (1 + frozenVulnerabilityBonus));
   }
   const poisonVulnerabilityBonus = target === cpu
    && target
    && Number(target.poisonTurns || 0) > 0
    && Number(target.poisonVulnerabilityTurns || 0) > 0
    ? 0.5
    : 0;
   const poisonVulnerabilityApplied = poisonVulnerabilityBonus > 0 && incomingDamage > 0;
   if (poisonVulnerabilityApplied) {
    incomingDamage = Math.ceil(incomingDamage * (1 + poisonVulnerabilityBonus));
   }
   const vulnerableCurseCards = target === player && incomingDamage > 0 ? getHandCurseCards('curse-vulnerable') : [];
   if (vulnerableCurseCards.length > 0) {
    const curseBonus = vulnerableCurseCards.reduce((total, card) => total + getCurseCardValue(card, 2), 0);
    incomingDamage += curseBonus;
    addLog(`呪いが傷を広げた：ダメージ+${curseBonus}`);
   }
   const ignoreBlock = Boolean(options.ignoreBlock);
   const preserveBlock = Boolean(options.preserveBlock);

   const defenseDown = target === cpu && target.defenseDownTurns > 0 ? (target.defenseDownValue || 0) : 0;
   const effectiveBlock = ignoreBlock ? 0 : Math.max(0, (target.block || 0) - defenseDown);
   const blocked = Math.min(effectiveBlock, incomingDamage);
   const actualDamage = incomingDamage - blocked;
   let endured = false;

   if (target === cpu && cpu && enemyHasPassive('tenacity') && !cpu.enemyTenacityUsed && actualDamage > 0 && target.hp - actualDamage <= 0) {
    cpu.enemyTenacityUsed = true;
    cpu.enemyTenacityTriggered = true;
    target.hp = 1;
    endured = true;
    addLog(`${getEnemyName()}：執念でHP1に踏みとどまった`);
   } else if (target === player && player && player.endureNextAttack && actualDamage > 0) {
    player.endureNextAttack = false;
    if (target.hp - actualDamage <= 0) {
     target.hp = 1;
     endured = true;
    } else {
     target.hp -= actualDamage;
    }
   } else if (target === player && player && playerPassives.tenacityOnce && !playerPassives.tenacityUsed && actualDamage > 0 && target.hp - actualDamage <= 0) {
    playerPassives.tenacityUsed = true;
    target.hp = 1;
    endured = true;
    addLog('執念：致死ダメージをHP1で耐えた');
   } else {
    target.hp -= actualDamage;
   }

   if (!preserveBlock) {
    target.block = Math.max(0, target.block - incomingDamage);
   }
   if (target === player) {
    recordAchievementMax('maxBlock', player.block || 0);
   }

   if (target.hp < 0) target.hp = 0;

   const dealtDamage = beforeHp - target.hp;

   if (target === cpu && dealtDamage > 0) {
   playSound('damage');
   if (enemyHasPassive('poison_blood') && options.poisonDamage) {
    const healAmount = Math.max(1, Math.floor(dealtDamage * 0.25));
    cpu.hp = Math.min(Number(cpu.maxHp || getEnemyMaxHp()), Number(cpu.hp || 0) + healAmount);
    showDamagePopup('cpu-hp-change', `+${healAmount}`);
    addLog(`${getEnemyName()}：毒血で${healAmount}回復`);
   }
  }

   if (battleResultStats && !battleResultStats.endedAt) {
    if (target === cpu) {
     battleResultStats.damageDealt += dealtDamage;
    } else if (target === player) {
     battleResultStats.damageTaken += dealtDamage;
    }
   }

   if (target === player && playerPassives.rareGuardCounter && actualDamage <= 0 && blocked > 0 && cpu && cpu.hp > 0) {
    const counterDamage = Math.floor(incomingDamage / 2);
    if (counterDamage > 0) {
     const counterResult = applyDamage(cpu, counterDamage, { ignoreBlock: true, preserveBlock: true });
     showDamagePopup('cpu-hp-change', `-${counterResult.damage}`);
     triggerDamageShake('.cpu-img');
     addLog(`ガードカウンター：${counterResult.damage}ダメージ反撃`);
    }
   }

   return {
    damage: dealtDamage,
    fullyBlocked: actualDamage <= 0,
    endured,
    frozenVulnerabilityApplied,
    poisonVulnerabilityApplied,
    lowHpReductionApplied,
   };
  }

  function consumePlayerReflectAttack(enemyCard, attackValue) {
   if (!player || !player.reflectNextAttack) return false;

   player.reflectNextAttack = false;

   const result = applyDamage(cpu, attackValue);

   showDamagePopup('player-hp-change', 'REFLECT');
   showDamagePopup('cpu-hp-change', `-${result.damage}`);
   triggerDamageShake('.cpu-img');
   triggerReflectEffect();
   triggerCardVisualEffect('.player-img', 'reflect-shield');
   triggerCardVisualEffect('.cpu-img', 'reflect-hit');

   if (result.damage > 0) {
    recordAchievementStat('reflectDamage', result.damage);
    if (cpu.hp <= 0) recordAchievementStat('reflectKills');
   }

   addLog(`${getEnemyName()}：${enemyCard.name}を反射 (${result.damage}ダメージ)`);
   playSound(result.fullyBlocked ? 'guard' : 'reflect');
   checkWinner();

   return true;
  }

  function decideCpuNextAction() {
   if (!cpu || !player || gameOver || cpu.hand.length === 0) return null;

   const selectableHand = cpu.lastActionName
    ? cpu.hand.filter(c => c.name !== cpu.lastActionName)
    : cpu.hand;
   const actionHand = selectableHand.length > 0 ? selectableHand : cpu.hand;

   const attacks = actionHand.filter(c => c.type === 'attack' || c.type === 'enemy-paralyze' || c.type === 'enemy-freeze' || c.type === 'enemy-burn' || c.type === 'enemy-poison' || c.type === 'enemy-bomb');
   const defenses = actionHand.filter(c => c.type === 'defense');
   const cleanses = actionHand.filter(c => c.type === 'enemy-cleanse');

   // 状態異常持ちの敵は25%で状態異常技を優先。
   // 直前と同じ技は候補から外す。ただし候補が1種類しかない場合は例外的に許可する。
   const statusCards = actionHand.filter(c =>
    c.type === 'enemy-paralyze' ||
    c.type === 'enemy-freeze' ||
    c.type === 'enemy-burn' ||
    c.type === 'enemy-poison' ||
    c.type === 'enemy-bomb' ||
    c.type === 'enemy-cleanse' ||
    c.type === 'freeze'
   );
   const currentEnemyIdForAction = getCurrentEnemyCatalogEntry()?.id;

   if (
    ['mage', 'storm_adept', 'ice_golem', 'crystal_serpent', 'abyss_reaper'].includes(currentEnemyIdForAction) &&
    statusCards.length > 0 &&
    Math.random() < 0.25
   ) {
    return statusCards[
     Math.floor(Math.random() * statusCards.length)
    ];
   }

   const lethalAttack = attacks.find(c => Math.max(0, c.value - player.block) >= player.hp);
   if (lethalAttack) return lethalAttack;

   if (cleanses.length > 0 && (cpu.paralysis > 0 || cpu.freeze > 0 || cpu.poisonTurns > 0 || cpu.burn) && Math.random() < 0.65) {
    return cleanses[Math.floor(Math.random() * cleanses.length)];
   }

   if (cpu.hp <= 10 && defenses.length > 0) {
    return defenses.sort((a, b) => b.value - a.value)[0];
   }

   if (attacks.length > 0) {
    return attacks.sort((a, b) => b.value - a.value)[0];
   }

   if (defenses.length > 0) {
    return defenses.sort((a, b) => b.value - a.value)[0];
   }

   if (cleanses.length > 0) {
    return cleanses[Math.floor(Math.random() * cleanses.length)];
   }

   return null;
  }

  function setCpuNextAction() {
   if (!cpu) return;
   cpu.nextAction = decideCpuNextAction();
   applyDangerSenseForNextAction();
  }

  function getCpuNextAction() {
   if (!cpu || !cpu.nextAction) return null;
   return cpu.nextAction;
  }

  

function getPetLevelBonusValue() {
 return Math.max(0, getEffectivePetLevel() - 1);
}

function getPetSkillPower(baseValue) {
 return baseValue + getPetLevelBonusValue();
}

function getPetAttackSkillPower(baseValue) {
 const multiplier = Math.max(1, Number(player?.currentPetAttackMultiplier || 1));
 return Math.round((getPetSkillPower(baseValue) + (playerPassives.petAttackPowerBonus || 0)) * multiplier);
}


const EVOLVED_PET_POWER_BONUS = 5;

function getEvolvedPetSkillPower(baseValue) {
 return getPetSkillPower(baseValue) + EVOLVED_PET_POWER_BONUS;
}

function getEvolvedPetAttackSkillPower(baseValue) {
 return getPetAttackSkillPower(baseValue) + EVOLVED_PET_POWER_BONUS;
}

function getPetSkillTurnBonus() {
 return Math.floor(getPetLevelBonusValue() / 2);
}

function getPetSkillPreviewText(skill) {
 if (!skill) return '???';

 const level = getEffectivePetLevel();
 const bonus = Math.max(0, level - 1);

 if (!skill.baseText) return skill.text;

 return bonus > 0
  ? `${skill.baseText} / Lv補正+${bonus}`
  : skill.baseText;
}


function isSelectedPetEvolved() {
 return Boolean(playerPassives?.rarePetEvolution) && getEffectivePetLevel() >= 10 && selectedPetId !== 'none';
}

