   if (type === 'defense-enhance') return '✨';
 if (type === 'rare-heal') return '🧘';
 if (type === 'rare-attack') return '💥';
   if (type === 'rare-double-attack') return '⚔️💥';
      if (type === 'self-damage-attack') return '🩸';
   if (type === 'blood-slash') return '🩸⚔️';
   if (type === 'berserk-strike') return '🩸💥';
   if (type === 'blood-awaken') return '🩸✨';
   if (type === 'blood-attack-buff') return '🩸⚔️';
