 if (type === 'rare-defense') return '✨';
   if (type === 'rare-attack-defense') return '⚔️🛡️';
   if (type === 'dein') return '🌩️';
   if (type === 'freeze') return '❄️';
   if (type === 'poison') return '☠️';
