   if (type === 'gamble-attack') return '🎲';
   if (type === 'double-slash') return '⚔️';
   if (type === 'pure-paralysis') return '⚡';
   if (type === 'attack-down') return '🌫️';
   if (type === 'defense-down') return '🪓';
   if (type === 'strip-defense') return '🪓';
   if (type === 'cooldown-boost') return '⏩';
   if (type === 'chance-attack') return '🎯';
   if (type === 'high-risk-attack') return '🎲';
