  const selfDamage = player ? Math.max(1, Math.floor(Number(player.hp || 0) * 0.2)) : 1;
  const baseDamage = selfDamage * Math.max(1, Number(card.value || 3));
  return getPlayerDamagePreviewValue(getEffectiveCardValue({ ...card, type: 'attack', value: baseDamage }));
