function getOwnedDeckEffectiveCardValue(card) {
 if (!card) return '';
 let value = Number(card.value || 0);

 if (isAttackCardType(card.type)) {
  return value + Math.max(0, Number(playerPassives.attack || 0));
 }

 if (isDefenseCardType(card.type)) {
  return value + Math.max(0, Number(playerPassives.defense || 0));
 }

 if (card.type === 'heal' || card.type === 'rare-heal') {
  return value + Math.max(0, Number(playerPassives.healBonus || 0));
 }

 return Number.isFinite(Number(card.value)) ? Number(card.value) : '';
}

function getOwnedDeckCardDisplayText(card) {
 if (!card) return '';
  const value = getOwnedDeckEffectiveCardValue(card);

  if (isBombCardType(card.type)) return getBaseCardDisplayText(card);
  if (card.type === 'attack' || card.type === 'rare-attack') return `${value}ダメージ`;
 if (card.type === 'defense' || card.type === 'rare-defense') return `防御+${value}`;
 if (card.type === 'heal' || card.type === 'rare-heal') return `${value}回復`;
 if (card.type === 'dein') return `${value}ダメージ / 30%で麻痺${card.turns || 3}T付与`;
 if (card.type === 'freeze') return `${value}ダメージ / 凍結付与`;
 if (card.type === 'poison') return `${value}ダメージ / 毒${card.turns || 3}T付与`;
 if (String(card.type || '').startsWith('poison-')) return getBaseCardDisplayText(card);
 if (String(card.type || '').startsWith('pet-')) return getBaseCardDisplayText(card);
 if (card.type === 'burn') {
  const chanceText = card.chance != null ? `${Math.round(card.chance * 100)}%で` : '50%で';
  return `${value}ダメージ / ${chanceText}火傷${card.turns || 3}T付与`;
 }
 if (card.type === 'drain-sword') return `${value}ダメージ / 与えたダメージの1/2回復`;
 if (card.type === 'chance-attack') return `50%の確率で${value}ダメージ`;
 if (card.type === 'high-risk-attack') return `10%の確率で${value}ダメージ`;
 if (card.type === 'freeze-bonus-attack') return `${value}ダメージ / 凍結状態の相手に+${card.bonus || 10}ダメージ`;
 if (card.type === 'risky-self-attack') return `${value}ダメージ または 自分に${card.selfDamage || 5}ダメージ`;
 if (card.type === 'finisher-attack') return `${value}ダメージ / 敵HP50%以下なら+${card.bonus || 8}ダメージ`;
 if (card.type === 'burn-bonus-attack') return `${value}ダメージ / 火傷状態なら+${card.bonus || 5}`;
 if (card.type === 'timer-execute-attack') return `${value}ダメージ / 敵行動タイマー残り${card.threshold || 2}秒以下なら+${card.bonus || 10}`;
 if (card.type === 'pierce-attack') return `${value}ダメージ / 防御無視`;
 if (card.type === 'attack-defense') return `${value}ダメージ / 防御+${(card.defense || 3) + Math.max(0, Number(playerPassives.defense || 0))}`;
 if (card.type === 'rare-double-attack') return `2 × ${5 + Math.max(0, Number(playerPassives.attack || 0))}ダメージ`;
 if (card.type === 'double-slash') return `2 × ${2 + Math.max(0, Number(playerPassives.attack || 0))}ダメージ`;
 if (card.type === 'paralyze-bonus-attack') return `${2 + Math.max(0, Number(playerPassives.attack || 0))}ダメージ / 敵が麻痺なら追加5ダメージ`;

 return getBaseCardDisplayText(card);
}

function getOwnedDeckCardsHtml() {
 const entries = CARD_POOL
  .map(card => ({ card: { ...card }, count: Math.max(0, Number(deckCustomize[card.name] || 0)) }))
  .filter(item => item.count > 0)
  .sort((a, b) => a.card.name.localeCompare(b.card.name, 'ja'));

 if (entries.length === 0) {
  return '<div class="owned-deck-empty">所持カードがありません。</div>';
 }

 return entries.map(({ card, count }) => {
  const value = getOwnedDeckEffectiveCardValue(card);
  const valueHtml = value !== '' ? `<div class="owned-deck-card-value">${escapeHtml(value)}</div>` : '';
  return `
   <div class="owned-deck-card ${getCardVisualClass(card)} ${card.type}">
    <div class="owned-deck-card-main">
     <span class="owned-deck-card-icon">${escapeHtml(getCardIcon(card.type))}</span>
     <strong>${escapeHtml(card.name)}</strong>
     <span class="owned-deck-card-count">×${count}</span>
    </div>
    ${valueHtml}
    <div class="owned-deck-card-text">${escapeHtml(getOwnedDeckCardDisplayText(card))}</div>
    <div class="owned-deck-card-cooldown">${escapeHtml(getCardCooldownText(card))}</div>
   </div>
  `;
 }).join('');
}

