function clearPlayerParalysis() {
   if (player) {
    player.paralyzed = false;
    player.paralysisTimer = 0;
   }

   const cardsElement = document.getElementById('cards');

   if (cardsElement) {
    cardsElement.classList.remove('paralyzed-hand');
   }
  }

function updatePlayerParalysisVisual() {
   const cardsElement = document.getElementById('cards');

   if (!cardsElement) return;

   const isParalyzed = Boolean(
    player &&
    player.paralyzed === true &&
    Number(player.paralysisTimer || 0) > 0
   );

   if (isParalyzed) {
    cardsElement.classList.add('paralyzed-hand');
   } else {
    cardsElement.classList.remove('paralyzed-hand');
   }
  }


function getStatusBadgesHtml(target) {
   if (!target) return '';

   const badges = [];

   if (target.block && target.block > 0) {
    badges.push(`<div class="status-badge defense-badge">🛡 防御 <strong>${target.block}</strong></div>`);
   }

   if (target.enhanceNextAttack) {
    badges.push(`<div class="status-badge enhance-badge">✨ エンハンス</div>`);
   }

   if (target.bloodAwakenAttackBoostUses && target.bloodAwakenAttackBoostUses > 0) {
    badges.push(`<div class="status-badge blood-awaken-badge">🩸 血の覚醒 <strong>あと${target.bloodAwakenAttackBoostUses}枚</strong></div>`);
   }

   if (target.tempAttackBuffTurns && target.tempAttackBuffTurns > 0) {
    badges.push(`<div class="status-badge enhance-badge">⚔ 攻撃+${target.tempAttackBuffValue || 0} <strong>${target.tempAttackBuffTurns}T</strong></div>`);
   }

   if (target.enhanceNextDefense) {
    badges.push(`<div class="status-badge defenseup-badge">🛡 ディフェンスアップ</div>`);
   }

   if (target.reflectNextAttack) {
    badges.push(`<div class="status-badge reflect-badge">🪞 リフレクト</div>`);
   }

   if (target.endureNextAttack) {
    badges.push(`<div class="status-badge endure-badge">🛡 不屈</div>`);
   }

   if (target.statusGuardTurns && target.statusGuardTurns > 0) {
    badges.push(`<div class="status-badge guard-badge">✨ 状態異常無効 <strong>${target.statusGuardTurns}T</strong></div>`);
   }

   if (target.nextChanceCardGuaranteed) {
    badges.push(`<div class="status-badge chanceguarantee-badge">🎯 確率確定</div>`);
   }

   if (target.paralyzed && Number(target.paralysisTimer || 0) > 0) {
    badges.push(`<div class="status-badge paralysis-badge">⚡ 麻痺 <strong>${Number(target.paralysisTimer || 0).toFixed(1)}秒</strong></div>`);
   }

   if (target.frozen) {
    const remaining = target === player ? getFreezeRemainingClicks() : Number(target.freeze || 0);
    badges.push(`<div class="status-badge freeze-badge">❄ 凍結 <strong>あと${remaining}回</strong></div>`);
   }

   if (target.paralysis && target.paralysis > 0) {
    badges.push(`<div class="status-badge paralysis-badge">⚡ 麻痺 <strong>${target.paralysis}T</strong></div>`);
   }

   if (target.freeze && target.freeze > 0) {
    badges.push(`<div class="status-badge freeze-badge">❄ 凍結 <strong>${target.freeze}T</strong></div>`);
   }

   if (target.poisonTurns && target.poisonTurns > 0) {
    badges.push(`<div class="status-badge poison-badge">☠ 毒量 <strong>${target.poisonTurns}</strong></div>`);
   }
   if (target.poisonVulnerabilityTurns && target.poisonVulnerabilityTurns > 0) {
    badges.push(`<div class="status-badge poison-badge">☠ 侵食 <strong>${target.poisonVulnerabilityTurns}T</strong></div>`);
   }
   if (target.poisonGrowthPerTurn && target.poisonGrowthPerTurn > 0) {
    badges.push(`<div class="status-badge poison-badge">☠ 疫病 <strong>+${target.poisonGrowthPerTurn}</strong></div>`);
   }
   if (target.poisonImmune) {
    badges.push(`<div class="status-badge poison-badge">☠ 毒耐性 <strong>50%</strong></div>`);
   }

    if (target.burn) {
     badges.push(`<div class="status-badge burn-badge">🔥 火傷 <strong>${target.burnTurns || 0}T</strong></div>`);
    }

  if (Array.isArray(target.bombs) && target.bombs.length > 0) {
    target.bombs.forEach(bomb => {
      const bombPreviewMultiplier = Number(bomb.damageMultiplier || 1) * (target === cpu ? (1 + Math.max(0, Number(playerPassives.bombDamageBonusMultiplier || 0))) * getEnemyBombDamageMultiplier() : 1);
      badges.push(`<div class="status-badge bomb-badge">${escapeHtml(bomb.icon || '💣')} ${escapeHtml(bomb.name || '爆弾')} <strong>残り${Math.max(0, Number(bomb.count || 0))} / ${Math.round(Number(bomb.damage || 0) * bombPreviewMultiplier)}ダメ</strong></div>`);
    });
  }

    if (target.attackDownTurns && target.attackDownTurns > 0) {
    badges.push(`<div class="status-badge attackdown-badge">🌫 攻撃力-${target.attackDownValue || 2} <strong>${target.attackDownTurns}T</strong></div>`);
   }

   if (target.defenseDownTurns && target.defenseDownTurns > 0) {
    badges.push(`<div class="status-badge defensedown-badge">🪓 防御力-${target.defenseDownValue || 2} <strong>${target.defenseDownTurns}T</strong></div>`);
   }

   if (target.nextCardCooldownReduceUses && target.nextCardCooldownReduceUses > 0) {
    badges.push(`<div class="status-badge cooldownboost-badge">⏩ 硬直-${target.nextCardCooldownReduceAmount || 1}秒 <strong>あと${target.nextCardCooldownReduceUses}枚</strong></div>`);
   }

   if (target.enemyActionDelayTurns && target.enemyActionDelayTurns > 0) {
    badges.push(`<div class="status-badge actiondelay-badge">⏳ 行動+${target.enemyActionDelayAmount || 2}秒 <strong>${target.enemyActionDelayTurns}T</strong></div>`);
   }
   if (target.pendingEnemyActionDelayTurns && target.pendingEnemyActionDelayTurns > 0) {
    badges.push(`<div class="status-badge actiondelay-badge">⏳ 次行動後 +${target.pendingEnemyActionDelayAmount || 2}秒 <strong>${target.pendingEnemyActionDelayTurns}T</strong></div>`);
   }

   if (target.nextReloadDoublePlayReady) {
    badges.push(`<div class="status-badge reloadlink-badge">🔁 リロード待ち</div>`);
   }

   if (target.doublePlayNextCard) {
    badges.push(`<div class="status-badge reloadlink-badge">🔁 次カード <strong>2回プレイ</strong></div>`);
   }

   if (badges.length === 0) {
    return '<div class="status-badge empty-badge">状態異常なし</div>';
   }

   return badges.join('');
  }

