  function getDeckTotalFromCustomizeSnapshot(snapshot = savedDeckCustomize) {
   return Object.values(snapshot || {}).reduce((sum, count) => sum + Math.max(0, Number(count || 0)), 0);
  }

  function getPreDepartureCardSummaryText(card) {
   const text = String(getBaseCardDisplayText(card) || card?.text || '').trim();
   if (!text) return '効果なし';
   const normalized = text.replace(/\s+/g, ' ');
   return normalized.length > 72 ? `${normalized.slice(0, 72)}…` : normalized;
  }

  function getPreDepartureCardTypeLabel(card) {
   const category = getCardCustomizeCategory(card);
   if (category === 'attack') return '攻撃';
   if (category === 'defense') return '防御';
   if (category === 'status') return '状態';
   if (category === 'support') return '補助';
   return '汎用';
  }

  function getPreDepartureCardRarityLabel(card) {
   const rarity = getCardRarity(card);
   if (rarity === 'legendary') return 'レジェンダリー';
   if (rarity === 'epic') return 'エピック';
   if (rarity === 'rare') return 'レア';
   if (rarity === 'curse') return '呪い';
   return 'ノーマル';
  }

  function getPreDepartureCardDetailHtml(card, count) {
   if (!card) return '';
   return `
    <div class="predeparture-card-detail-content">
     <div class="predeparture-card-detail-icon">${escapeHtml(getCardIcon(card.type))}</div>
     <div class="predeparture-card-detail-body">
      <div class="predeparture-card-detail-kicker">CARD DETAIL</div>
      <h2>${escapeHtml(card.name)}</h2>
      <div class="predeparture-card-detail-meta">
       <span>レアリティ <strong>${escapeHtml(getPreDepartureCardRarityLabel(card))}</strong></span>
       <span>種別 <strong>${escapeHtml(getPreDepartureCardTypeLabel(card))}</strong></span>
       <span>枚数 <strong>×${Math.max(0, Number(count || 0))}</strong></span>
      </div>
      <div class="predeparture-card-detail-effect">
       <span>効果</span>
       <strong>${escapeHtml(getDynamicCardDisplayText(card))}</strong>
      </div>
     </div>
    </div>
   `;
  }

  function openPreDepartureCardDetail(cardName) {
   const card = CARD_POOL.find(item => item.name === cardName);
   if (!card) return;
   const modal = document.getElementById('predeparture-card-detail-modal');
   const content = document.getElementById('predeparture-card-detail-content');
   if (!modal || !content) return;
   const count = Math.max(0, Math.floor(Number(savedDeckCustomize?.[card.name] || 0)));
   playUiSelectSound();
   content.innerHTML = getPreDepartureCardDetailHtml(card, count);
   modal.style.display = 'flex';
  }

  function closePreDepartureCardDetail(event) {
   if (event && event.target && event.currentTarget && event.target !== event.currentTarget) return;
   const modal = document.getElementById('predeparture-card-detail-modal');
   if (modal) modal.style.display = 'none';
  }

  function getDeckPreviewCardsHtml(snapshot = savedDeckCustomize) {
   const entries = CARD_POOL
    .map(card => ({ card, count: Math.max(0, Math.floor(Number(snapshot?.[card.name] || 0))) }))
    .filter(entry => entry.count > 0);

   if (!entries.length) {
    return '<div class="predeparture-empty">山札にカードがありません。</div>';
   }

   return entries.map(({ card, count }) => `
    <button class="predeparture-deck-card predeparture-rarity-${escapeHtml(getCardRarity(card))} predeparture-type-${escapeHtml(getCardCustomizeCategory(card))}" type="button" onclick="openPreDepartureCardDetail('${String(card.name).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}')">
     <div class="predeparture-deck-card-top">
      <span class="predeparture-deck-card-icons">${escapeHtml(getCardIcon(card.type))}</span>
      <strong>${escapeHtml(card.name)}</strong>
      <em>×${count}</em>
     </div>
     <p>${escapeHtml(getPreDepartureCardSummaryText(card))}</p>
     <div class="predeparture-deck-card-tags">
      <span>${escapeHtml(getPreDepartureCardTypeLabel(card))}</span>
      <span>${escapeHtml(getPreDepartureCardRarityLabel(card))}</span>
     </div>
    </button>
   `).join('');
  }

  function getPreDeparturePetHtml() {
   const pet = getPetById(selectedPetId || 'none');
   const level = selectedPetId === 'none' ? '-' : getPetLevelFromExp(petExp);
   const skillHtml = selectedPetId === 'none'
    ? '<div class="pet-skill-empty">ペットが未選択です。</div>'
    : getPetSkillListHtml(pet?.skills || [], '使用できる技はありません。');
   const imageHtml = pet?.image
    ? `<img src="${pet.image}" alt="${escapeHtml(pet.name)}" onerror="this.style.display='none'; this.nextElementSibling.style.display='flex';"><div class="predeparture-placeholder" style="display:none;">${escapeHtml(pet.placeholder || 'PET')}</div>`
    : `<div class="predeparture-placeholder">${escapeHtml(pet?.placeholder || 'PET')}</div>`;

   return `
    <section class="predeparture-panel predeparture-pet-panel">
     <div class="predeparture-panel-head">
      <h2>ペット</h2>
      <button class="ui-button ui-button-secondary" onclick="showPetSelectFromPreDeparture()">ペット変更</button>
     </div>
     <div class="predeparture-pet-body">
      <div class="predeparture-pet-image">${imageHtml}</div>
      <div>
       <div class="predeparture-main-name">${escapeHtml(pet?.name || 'なし')}</div>
       <div class="predeparture-meta-grid">
        <span>レベル <strong>${escapeHtml(String(level))}</strong></span>
       </div>
       <div class="predeparture-pet-skills">
        <div class="predeparture-subtitle">技一覧</div>
        ${skillHtml}
       </div>
      </div>
     </div>
    </section>
   `;
  }

  function getPreDepartureDeckHtml() {
   return `
    <section class="predeparture-panel predeparture-deck-panel">
     <div class="predeparture-panel-head">
      <h2>山札</h2>
      <button class="ui-button ui-button-secondary" onclick="showCustomizeFromPreDeparture()">山札編集</button>
     </div>
     <div class="predeparture-deck-summary">デッキ枚数：<strong>${getDeckTotalFromCustomizeSnapshot()}枚</strong></div>
     <div class="predeparture-deck-list">${getDeckPreviewCardsHtml()}</div>
    </section>
   `;
  }

  function getPreDepartureRelicHtml() {
   const equipment = normalizeRelicEquipment(loadRelicEquipment());
   const slotCards = equipment.slots.map((relicId, index) => {
    const unlocked = index < equipment.unlockedSlotCount;
    const relic = unlocked && relicId && hasRelic(relicId) ? getRelicById(relicId) : null;
    return relic ? `
     <div class="predeparture-relic-body">
      <div class="predeparture-relic-icon">${escapeHtml(relic.icon || '◆')}</div>
      <div>
       <div class="predeparture-relic-slot-label">${escapeHtml(getRelicSlotLabel(index))}</div>
       <div class="predeparture-main-name">${escapeHtml(relic.name)}</div>
       <p>${escapeHtml(relic.effect)}</p>
      </div>
     </div>
    ` : `
     <div class="predeparture-relic-body empty${unlocked ? '' : ' locked'}">
      <div class="predeparture-relic-icon">${unlocked ? '◆' : '🔒'}</div>
      <div>
       <div class="predeparture-relic-slot-label">${escapeHtml(getRelicSlotLabel(index))}</div>
       <div class="predeparture-main-name">${unlocked ? '未装備' : '未解放'}</div>
       <p>${escapeHtml(unlocked ? '取得済み遺物から装備できます。' : getRelicSlotUnlockText(index))}</p>
      </div>
     </div>
    `;
   }).join('');
   return `
    <section class="predeparture-panel predeparture-relic-panel">
     <div class="predeparture-panel-head">
      <h2>遺物</h2>
      <button class="ui-button ui-button-secondary" onclick="showRelicEquipScreen()">遺物変更</button>
     </div>
     <div class="predeparture-relic-slots">${slotCards}</div>
    </section>
   `;
  }

  function renderPreDepartureScreen() {
   const content = document.getElementById('predeparture-content');
   if (!content) return;
   content.innerHTML = `
    <div class="predeparture-grid">
     ${getPreDeparturePetHtml()}
     ${getPreDepartureRelicHtml()}
     ${getPreDepartureDeckHtml()}
    </div>
   `;
  }

  function showPreDepartureScreen() {
   playUiSelectSound();
   if (currentScreen === 'customize') {
    deckCustomize = structuredClone(savedDeckCustomize);
   }
   stopEnemyTimer();
   stopReload();
   stopCooldown();
   stopDeckReload();
   stopPlayerStatusTimer();
   currentScreen = 'predeparture';
   renderPreDepartureScreen();
   render();
  }

  function getHighestReachedLevelForMenu() {
   const statsLevel = Number(loadAchievementStats()?.highestLevel || 0);
   const historyLevel = loadBattleHistory().reduce((max, item) => Math.max(max, Number(item.reachedLevel || 0)), 0);
   return Math.max(statsLevel, historyLevel, 0);
  }

  function getMenuStatusSummaryHtml() {
   const pet = getPetById(selectedPetId || 'none');
   const highestClearedDepth = getHighestClearedDepth();
   return `
    <div class="menu-status-item"><span>プレイヤー名</span><strong>${escapeHtml(getCurrentPlayerName() || 'player')}</strong></div>
    <div class="menu-status-item"><span>現在の深度</span><strong>${escapeHtml(getDepthLabel(currentDepth))}</strong></div>
    <div class="menu-status-item"><span>選択中のペット</span><strong>${escapeHtml(pet?.name || 'なし')}</strong></div>
    <div class="menu-status-item"><span>山札枚数</span><strong>${getDeckTotalFromCustomizeSnapshot()}枚</strong></div>
    <div class="menu-status-item"><span>最高到達Lv</span><strong>Lv.${getHighestReachedLevelForMenu()}</strong></div>
    <div class="menu-status-item"><span>最高クリア深度</span><strong>${highestClearedDepth > 0 ? `深度${highestClearedDepth}` : '未クリア'}</strong></div>
   `;
  }

  function renderMenuStatusSummary() {
   ['prepare-status-summary'].forEach(id => {
    const element = document.getElementById(id);
    if (element) element.innerHTML = getMenuStatusSummaryHtml();
   });
  }

  const saveSlotsView = window.GameSaveSlotsView.createSaveSlotsView({
   saveSlotCount: SAVE_SLOT_COUNT,
   getCurrentSaveSlot: () => currentSaveSlot,
   getAllSaveSlotSummaries,
   loadGameDataFromSlot,
   saveCurrentGameDataToSlot,
  });

  function renderSaveSlotList(mode) {
   return saveSlotsView.renderSaveSlotList(mode);
  }

  function renderClearScreen() {
   const clearScreen = document.getElementById('clear-screen');
   if (!clearScreen) return;

   const depth = normalizeDepth(lastClearedDepth || currentDepth);
   const depthLabel = getDepthLabel(depth);
   const kicker = clearScreen.querySelector('.clear-kicker');
   const title = clearScreen.querySelector('h1');
   const description = clearScreen.querySelector('.title-description');
   const clearCard = clearScreen.querySelector('.clear-card') || clearScreen.querySelector('.title-card');

   if (kicker) kicker.textContent = `${depthLabel.toUpperCase()} CLEAR`;
   if (title) title.textContent = `${depthLabel}クリア！`;
   if (description) description.textContent = `${depthLabel}の最深部を踏破しました。`;

   if (clearCard) {
    let rewardElement = clearCard.querySelector('.clear-relic-reward');
    if (!rewardElement) {
     rewardElement = document.createElement('div');
     rewardElement.className = 'clear-relic-reward';
     const actions = clearCard.querySelector('.clear-actions');
     if (actions) {
      clearCard.insertBefore(rewardElement, actions);
     } else {
      clearCard.appendChild(rewardElement);
     }
    }
    rewardElement.innerHTML = getRelicRewardHtml(lastRelicReward);
    rewardElement.style.display = lastRelicReward ? 'block' : 'none';
   }
  }


function render() {

   if (currentScreen === 'card-library') {
    renderCardLibraryScreen();
   }

   if (currentScreen === 'collection') {
    renderCollectionScreen();
   }

   if (currentScreen === 'enemy-library') {
    renderEnemyLibraryScreen();
   }

   if (currentScreen === 'passive-library') {
    renderPassiveLibraryScreen();
   }

   if (currentScreen === 'achievement-library') {
    renderAchievementLibraryScreen();
   }
   if (currentScreen === 'random-event-library') {
    renderRandomEventLibraryScreen();
   }

   if (currentScreen === 'relic-library') {
    renderRelicLibraryScreen();
   }

   if (currentScreen === 'relic-equip') {
    renderRelicEquipScreen();
   }

   if (currentScreen === 'pet-library') {
    renderPetLibraryScreen();
   }

   if (currentScreen === 'battle-history') {
    renderBattleHistoryScreen();
   }

   updateShopModalVisibility();
   syncMenuBgm();

   const startScreen = document.getElementById('start-screen');
   if (startScreen) {
    startScreen.style.display = currentScreen === 'start' ? 'flex' : 'none';
    const loadButton = document.getElementById('load-game-button');
    if (loadButton) loadButton.disabled = false;
   }

   const playerNameScreen = document.getElementById('player-name-screen');
   if (playerNameScreen) {
    playerNameScreen.style.display = currentScreen === 'player-name' ? 'flex' : 'none';
   }

   const depthSelectScreen = document.getElementById('depth-select-screen');
   if (depthSelectScreen) {
    depthSelectScreen.style.display = currentScreen === 'depth-select' ? 'flex' : 'none';
    if (currentScreen === 'depth-select') renderDepthSelector();
   }

   const prepareScreen = document.getElementById('prepare-screen');
   if (prepareScreen) {
    prepareScreen.style.display = currentScreen === 'prepare' ? 'flex' : 'none';
   }

   const predepartureScreen = document.getElementById('predeparture-screen');
   if (predepartureScreen) {
    predepartureScreen.style.display = currentScreen === 'predeparture' ? 'flex' : 'none';
    if (currentScreen === 'predeparture') renderPreDepartureScreen();
   }

   const loadSlotScreen = document.getElementById('load-slot-screen');
   if (loadSlotScreen) {
    loadSlotScreen.style.display = currentScreen === 'load-slot' ? 'flex' : 'none';
    if (currentScreen === 'load-slot') renderSaveSlotList('load');
   }

   const saveSlotScreen = document.getElementById('save-slot-screen');
   if (saveSlotScreen) {
    saveSlotScreen.style.display = currentScreen === 'save-slot' ? 'flex' : 'none';
    if (currentScreen === 'save-slot') renderSaveSlotList('save');
   }

   document.getElementById('title-screen').style.display = currentScreen === 'title' ? 'flex' : 'none';
   renderMenuStatusSummary();
   document.getElementById('collection-screen').style.display = currentScreen === 'collection' ? 'flex' : 'none';
   document.getElementById('card-library-screen').style.display = currentScreen === 'card-library' ? 'flex' : 'none';
   document.getElementById('enemy-library-screen').style.display = currentScreen === 'enemy-library' ? 'flex' : 'none';
   document.getElementById('passive-library-screen').style.display = currentScreen === 'passive-library' ? 'flex' : 'none';
   document.getElementById('achievement-library-screen').style.display = currentScreen === 'achievement-library' ? 'flex' : 'none';
   document.getElementById('random-event-library-screen').style.display = currentScreen === 'random-event-library' ? 'flex' : 'none';
   document.getElementById('relic-library-screen').style.display = currentScreen === 'relic-library' ? 'flex' : 'none';
   document.getElementById('relic-equip-screen').style.display = currentScreen === 'relic-equip' ? 'flex' : 'none';
   document.getElementById('pet-library-screen').style.display = currentScreen === 'pet-library' ? 'flex' : 'none';
   document.getElementById('battle-history-screen').style.display = currentScreen === 'battle-history' ? 'flex' : 'none';
   const rankingScreen = document.getElementById('ranking-screen');
   if (rankingScreen) rankingScreen.style.display = currentScreen === 'ranking' ? 'flex' : 'none';
   document.getElementById('help-screen').style.display = currentScreen === 'help' ? 'flex' : 'none';
   if (currentScreen === 'help') setupHelpGuideCards();
   document.getElementById('clear-screen').style.display = currentScreen === 'clear' ? 'flex' : 'none';
   if (currentScreen === 'clear') renderClearScreen();
   document.getElementById('customize-screen').style.display = currentScreen === 'customize' ? 'block' : 'none';
   document.getElementById('pet-select-screen').style.display = currentScreen === 'pet-select' ? 'block' : 'none';
   document.getElementById('battle-screen').style.display = currentScreen === 'battle' ? 'block' : 'none';

   if (currentScreen === 'customize') {
    renderCustomizeScreen();
    return;
   }

   if (currentScreen === 'pet-select') {
    renderPetSelectScreen();
    return;
   }

   renderRandomEventModal();

   if (currentScreen !== 'battle' || !player || !cpu) return;

   checkPetEvolutionTrigger();

   const battleArea = document.getElementById('battle-area');

   if (battleArea) {
    battleArea.classList.toggle('has-pet', selectedPetId !== 'none');
    battleArea.classList.toggle('no-pet', selectedPetId === 'none');

   }


   renderStatusBadges();
   renderPassiveEffectBadges();

   document.getElementById('deck-count').textContent = `${deckCount}枚`;
   updateDeckHoverDetail();

   const deckReloadStatus = document.getElementById('deck-reload-status');
   const deckReloadCount = document.getElementById('deck-reload-count');

   deckReloadStatus.style.display = 'none';
   if (deckReloadCount) deckReloadCount.textContent = '';
   updateEnemyTimerText();

   document.getElementById('enemy-level').textContent = getDisplayEnemyLevel();

   const vsEnemyTimerValue = document.getElementById('vs-enemy-timer-value');

   if (vsEnemyTimerValue && cpu) {
    const remain = Math.max(0, Number(cpu.actionTimer || 0));
    vsEnemyTimerValue.textContent = `${remain.toFixed(1)}秒`;
   }


 const enemyImg = document.querySelector('.cpu-img');
   if (enemyImg) {
    enemyImg.src = getEnemyImageSrc();
   }
   document.getElementById('enemy-name').textContent = getEnemyName();

   const enemyImage = document.getElementById('enemy-image');
   const nextEnemyImageSrc = getEnemyImageSrc();

   if (enemyImage.getAttribute('src') !== nextEnemyImageSrc) {
    enemyImage.src = nextEnemyImageSrc;
   }

   enemyImage.alt = getEnemyName();

   if (pendingVoidEntranceAnimation && enemyLevel >= 20 && cpu && cpu.phase === 1) {
    pendingVoidEntranceAnimation = false;
    setTimeout(triggerVoidEntranceAnimation, 30);
   }

   document.getElementById('player-hp').textContent = `${player.hp} / ${getPlayerMaxHp()}`;
   document.getElementById('cpu-hp').textContent = `${cpu.hp} / ${getEnemyMaxHp()}`;
   const passiveTexts = [];
   if (playerPassives.attack > 0) {
    passiveTexts.push(`攻撃+${playerPassives.attack}`);
   }
   if (playerPassives.defense > 0) {
    passiveTexts.push(`防御+${playerPassives.defense}`);
   }
   if (playerPassives.maxHp > 0) {
    passiveTexts.push(`最大HP+${playerPassives.maxHp}`);
   }
   if (playerPassives.reloadDrawBonus > 0) {
    passiveTexts.push(`ドロー+${playerPassives.reloadDrawBonus}`);
   }
   if (playerPassives.enemyDelay > 0) {
    passiveTexts.push(`敵遅延+${playerPassives.enemyDelay}`);
   }
   if (playerPassives.frozenVulnerabilityDamageBonus > 0) {
    passiveTexts.push(`凍結中ダメ+${Math.round(playerPassives.frozenVulnerabilityDamageBonus * 100)}%`);
   }
   document.getElementById('player-block').textContent =
    `防御: ${player.block}`
    + (passiveTexts.length > 0
     ? ` / ${passiveTexts.join('')}`
     : '');
   document.getElementById('cpu-block').textContent =
   `防御: ${cpu.block}`
    + `${isEnemyParalysisImmune() ? ' / 麻痺無効' : ''}`
    + `${isEnemyFreezeImmune() ? ' / 凍結無効' : ''}`
    + `${isEnemyBurnImmune() ? ' / 火傷無効' : ''}`
    + `${cpu.paralysis && cpu.paralysis > 0 ? ` / 麻痺:${cpu.paralysis}` : ''}`
     + `${cpu.freeze && cpu.freeze > 0 ? ` / 凍結` : ''}`
     + `${cpu.poisonTurns && cpu.poisonTurns > 0 ? ` / 毒量:${cpu.poisonTurns}` : ''}`
     + `${cpu.poisonImmune ? ' / 毒耐性' : ''}`
     + `${cpu.burn && cpu.burnTurns && cpu.burnTurns > 0 ? ` / 火傷:${cpu.burnTurns}T` : (cpu.burn ? ' / 火傷' : '')}`
     + `${cpu.bombs && cpu.bombs.length > 0 ? ` / 爆弾:${cpu.bombs.length}個` : ''}`;

   const playerHpFill = document.getElementById('player-hp-fill');
   const cpuHpFill = document.getElementById('cpu-hp-fill');

   playerHpFill.style.width = `${(player.hp / getPlayerMaxHp()) * 100}%`;
   cpuHpFill.style.width = `${(cpu.hp / getEnemyMaxHp()) * 100}%`;

   playerHpFill.classList.toggle('guarded', player.block > 0);
   cpuHpFill.classList.toggle('guarded', cpu.block > 0);

   const reloadStatus = document.getElementById('reload-status');
   const reloadCount = document.getElementById('reload-count');

   reloadStatus.style.display = player.reloading ? 'flex' : 'none';
   reloadCount.textContent = player.reloading ? `${Math.max(0, Number(player.reloadTimer || 0)).toFixed(1)}秒` : '';

   const cooldownStatus = document.getElementById('cooldown-status');
   const cooldownCount = document.getElementById('cooldown-count');

   cooldownStatus.style.display = player.cooldown ? 'flex' : 'none';
   cooldownCount.textContent = player.cooldown ? `${player.cooldownTimer.toFixed(1)}秒` : '';

   const manualReloadButton = document.getElementById('manual-reload-button');
   if (manualReloadButton) {
    const reloadQueueNumber = getQueuedReloadNumber();
    const canReloadQueueClick = canQueueActionNow() || reloadQueueNumber > 0;
    manualReloadButton.disabled = bossRevivalInProgress || pendingPassiveChoice || isRandomEventInputBlocked() || player.reloading || gameOver || isPlayerFrozen() || (player.cooldown && !canReloadQueueClick);
    manualReloadButton.classList.toggle('action-queue-enabled', canReloadQueueClick);
    manualReloadButton.classList.toggle('action-queued', reloadQueueNumber > 0);
    manualReloadButton.innerHTML = `${reloadQueueNumber > 0 ? `<span class="action-queue-badge">${getActionQueueLabel(reloadQueueNumber)}</span>` : ''}リロード`;
   }


   
   /* update paralysis visual after cards render */
   updatePlayerParalysisVisual();

const nextAction = getCpuNextAction();
   const prediction = document.getElementById('cpu-next-action');

   if (prediction && nextAction) {
    const isStatusAttack = ['enemy-paralyze','enemy-freeze','enemy-burn','enemy-poison','enemy-bomb'].includes(nextAction.type);

    const kind = nextAction.type === 'defense'
     ? '防御'
     : nextAction.type === 'enemy-cleanse'
      ? '補助'
      : isStatusAttack
       ? '特殊攻撃'
       : '攻撃';

    let valueText = '';

    if (nextAction.type === 'defense') {
     valueText = `防御 ${nextAction.value}`;
    } else if (nextAction.type === 'enemy-cleanse') {
     valueText = '自身の状態異常を全解除 + 自身に凍結';
    } else if (nextAction.type === 'enemy-paralyze') {
     valueText = `${nextAction.value}ダメージ + 麻痺`;
    } else if (nextAction.type === 'enemy-freeze') {
     valueText = `${nextAction.value}ダメージ + 凍結`;
    } else if (nextAction.type === 'enemy-burn') {
     valueText = `${nextAction.value}ダメージ + 火傷`;
    } else if (nextAction.type === 'enemy-poison') {
     valueText = `${nextAction.value}ダメージ + 毒`;
    } else if (nextAction.type === 'enemy-bomb') {
     valueText = `${nextAction.value}ダメージ + 爆弾`;
    } else {
     valueText = `${nextAction.value}ダメージ`;
    }
    prediction.innerHTML = `
     <div class="cpu-prediction-label">👁 次の行動予測</div>
     <div class="cpu-prediction-main">
      <span class="cpu-prediction-name">${escapeHtml(nextAction.name)}</span>
      <span class="cpu-prediction-kind">${kind}</span>
      <span class="cpu-prediction-value">${valueText}</span>
     </div>
    `;
   } else if (prediction) {
    prediction.innerHTML = '<div class="cpu-prediction-label">👁 次の行動予測</div><div class="cpu-prediction-none">なし</div>';
   }

   
   
   const selectedPet = getDisplayPet();
   const petTitle = document.getElementById('pet-title');
   const petImage = document.getElementById('pet-image');
   const petPlaceholder = document.getElementById('pet-placeholder');

   const petPanel = document.getElementById('pet-panel');

   if (petPanel && selectedPet && selectedPet.id === 'none') {
    petPanel.style.display = 'none';
   } else if (petPanel) {
    petPanel.style.display = 'block';
    petPanel.classList.toggle('pet-evolved', Boolean(selectedPet?.evolved));
   }

  if (petTitle && petImage && petPlaceholder && selectedPet && selectedPet.id !== 'none') {
    petTitle.textContent = `ペット：${selectedPet.name} Lv.${getEffectivePetLevel() >= MAX_PET_LEVEL ? 'MAX' : getEffectivePetLevel()}`;
    petPlaceholder.textContent = selectedPet.placeholder;
    petPlaceholder.style.display = 'none';
    petImage.style.display = '';
    petImage.src = selectedPet.image;
    petImage.alt = selectedPet.name;
   }

const petCharge = document.getElementById('pet-charge');
   const petLastAction = document.getElementById('pet-last-action');

   if (petCharge && petLastAction) {
    const expText = getPetExpStatusText();
    petCharge.textContent = `行動まであと：${Math.max(0, getPetActionRequiredCardCount() - (player.petCardUseCount || 0))}${expText ? ` / ${expText}` : ''}`;
    petLastAction.innerHTML = `
     <div class="pet-next-action">次行動：${getPetNextSkillPreview()}</div>
    `;
   }

const cards = document.getElementById('cards');

   if (cards) {
    cards.onclick = handleHandAreaClick;
   }

   if (cards && player) {
    cards.classList.toggle('paralyzed-hand', Boolean(player.paralyzed && player.paralysisTimer > 0));
    cards.classList.toggle('frozen-hand', isPlayerFrozen());
   }


   cards.innerHTML = '';

   if (player.reloading) {
    cards.innerHTML = `<div class="reload-panel">リロード中... ${Math.max(0, Number(player.reloadTimer || 0)).toFixed(1)}秒</div>`;
   } else {
    player.hand.forEach(card => {
     const button = document.createElement('button');
     const queueNumber = getQueuedCardNumber(card.id);
     const canQueueClick = canQueueActionNow() || queueNumber > 0;
     const inactive = bossRevivalInProgress || pendingPassiveChoice || pendingShopChoice || isRandomEventInputBlocked() || isPlayerFrozen();

     button.className = `card ${getCardVisualClass(card)} ${card.type || ''} ${card.type ? `${card.type}-card` : ''}${getCardRarityClass(card)}${(player.cooldown || inactive) ? ' disabled' : ''}${canQueueClick ? ' action-queue-enabled' : ''}${queueNumber > 0 ? ' action-queued' : ''}`;
     button.dataset.cardId = card.id;

     const displayValue = getBattleCardDisplayValue(card);
     const displayText = getDisplayCardText(card);

     button.innerHTML = `
      ${queueNumber > 0 ? `<div class="action-queue-badge">${getActionQueueLabel(queueNumber)}</div>` : ''}
      <div class="card-shine"></div>
      ${hasCardRarityDisplay(card) ? `<div class="rare-badge">${getCardRarityBadge(card)}</div>` : ''}
      <div class="card-top">
       <div>${card.name}</div>
       <div class="card-icon">${getCardIcon(card.type)}</div>
      </div>
      <div class="value">${displayValue}</div>
      <div class="card-text">${displayText}</div>
      <div class="card-cooldown">${getEffectiveCardCooldownText(card)}</div>
     `;

     cards.appendChild(button);
    });
   }

   const battleMenuPanel = document.getElementById('battle-menu-panel');
   const battleMenuButton = document.getElementById('battle-menu-button');
   if (battleMenuPanel) {
    battleMenuPanel.style.display = battleMenuOpen ? 'flex' : 'none';
   }
   if (battleMenuButton) {
    battleMenuButton.setAttribute('aria-expanded', battleMenuOpen ? 'true' : 'false');
    battleMenuButton.classList.toggle('is-open', battleMenuOpen);
   }

   const logPanel = document.getElementById('log-panel');
   const logToggleButton = document.getElementById('log-toggle-button');

   if (logPanel) logPanel.style.display = logVisible ? 'block' : 'none';
   if (logToggleButton) logToggleButton.textContent = logVisible ? 'ログを非表示' : 'ログを表示';

   const log = document.getElementById('log');

   log.innerHTML = '';

   logs.forEach(item => {
    const div = document.createElement('div');

    div.className = 'log-item';
    div.textContent = item;

    log.appendChild(div);
   });

   const winner = document.getElementById('winner');
   const victoryActions = document.getElementById('victory-actions');

   const passiveActions = document.getElementById('passive-actions');
   const passiveOptions = document.getElementById('passive-options');

   if (passiveActions && passiveOptions) {
    if (pendingPassiveChoice) {
     passiveActions.style.display = 'flex';
     renderOwnedDeckLists();
     passiveOptions.innerHTML = '';

     currentPassiveChoices.forEach(option => {
      const button = document.createElement('button');

      button.className = `passive-card${option.rarity === 'rare' ? ' rare-passive-card' : ''}`;
      button.onclick = () => choosePassive(option.id);

      button.innerHTML = `
       <div class="passive-card-title">${option.icon} ${option.rarity === 'rare' ? '' : ''} ${option.name}</div>
       <div class="passive-card-text">${option.text}</div>
      `;

      passiveOptions.appendChild(button);
     });
    } else {
     passiveActions.style.display = 'none';
     passiveOptions.innerHTML = '';
     if (!pendingShopChoice) {
      ownedDeckModalOpen = false;
      ownedPassivesModalOpen = false;
      ownedPassivesModalHardClosed = false;
     }
     renderOwnedDeckModal();
     renderOwnedPassivesModal();
    }
   }



   const shopActions = document.getElementById('shop-actions');
   const shopOptions = document.getElementById('shop-options');
   const shopSelectedCount = document.getElementById('shop-selected-count');
   const shopRemoveOptions = document.getElementById('shop-remove-options');
   const shopRerollButton = document.getElementById('shop-reroll-button');

   if (shopActions && shopOptions && shopSelectedCount) {
    if (pendingShopChoice && currentShopCards.length > 0) {
     const pickLimit = getShopCardPickLimit();
     shopActions.style.display = 'flex';
     renderOwnedDeckLists();
     shopOptions.innerHTML = '';
     const rerollLimit = getShopRerollLimit();
     shopSelectedCount.textContent = `選択中：${selectedShopCardIds.length} / ${pickLimit}${selectedShopRemoveCardName ? '（削除選択中のため-1）' : ''}${rerollLimit > 0 ? ` / リロール：${currentShopRerollsUsed} / ${rerollLimit}` : ''}`;
     if (shopRerollButton) {
      shopRerollButton.style.display = rerollLimit > 0 ? 'inline-flex' : 'none';
      shopRerollButton.disabled = currentShopRerollsUsed >= rerollLimit;
      shopRerollButton.textContent = `リロール (${Math.max(0, rerollLimit - currentShopRerollsUsed)}回)`;
     }

     currentShopCards.forEach(card => {
      const button = document.createElement('button');
      const selected = selectedShopCardIds.includes(card.shopId);
      const disabled = !selected && selectedShopCardIds.length >= pickLimit;
      // ショップのカードは未取得カードのプレビューなので、戦闘中の一時強化
      // （エンハンス/ディフェンスアップ）やパッシブ補正（攻撃アップ等）を乗せない。
      const displayValue = Number.isFinite(Number(card.value)) ? Number(card.value) : '';
      const displayText = getBaseCardDisplayText(card);

      button.className = `shop-card ${getCardVisualClass(card)} ${card.type}${getCardRarityClass(card)}${selected ? ' selected' : ''}`;
      button.disabled = disabled;
      button.onclick = () => toggleShopCard(card.shopId);

      button.innerHTML = `
       <div class="card-shine"></div>
       ${selected ? '<div class="selected-badge">選択中 ✓</div>' : ''}
       ${hasCardRarityDisplay(card) ? `<div class="rare-badge">${getCardRarityBadge(card)}</div>` : ''}
       <div class="card-top">
        <div>${card.name}</div>
        <div class="card-icon">${getCardIcon(card.type)}</div>
       </div>
       <div class="value">${displayValue}</div>
       <div class="card-text">${displayText}</div>
       <div class="card-cooldown">${getCardCooldownText(card)}</div>
      `;

      shopOptions.appendChild(button);
     });

     if (shopRemoveOptions) {
      shopRemoveOptions.innerHTML = '';
      const removableCards = getRemovableDeckCards();

      if (removableCards.length === 0) {
       const empty = document.createElement('div');
       empty.className = 'shop-remove-empty';
       empty.textContent = '削除できるカードがありません。';
       shopRemoveOptions.appendChild(empty);
      } else {
       removableCards.forEach(card => {
        const button = document.createElement('button');
        const selected = selectedShopRemoveCardName === card.name;

        button.className = `shop-remove-card ${selected ? 'selected' : ''}`;
        button.onclick = () => toggleShopRemoveCard(card.name);
        button.innerHTML = `
         <span>${card.name}</span>
         <strong>×${card.count}</strong>
        `;

        shopRemoveOptions.appendChild(button);
       });
      }
     }
    } else {
     shopActions.style.display = 'none';
      ownedDeckModalOpen = false;
     ownedPassivesModalOpen = false;
     ownedPassivesModalHardClosed = false;
     shopOptions.innerHTML = '';
     if (shopRemoveOptions) shopRemoveOptions.innerHTML = '';
     if (shopRerollButton) shopRerollButton.style.display = 'none';
    }
   }

   const victoryResult = document.getElementById('victory-result');
   const resultHeading = document.getElementById('battle-result-heading');
   const resultMessage = document.getElementById('battle-result-message');
   const resultNextButton = document.getElementById('battle-result-next-button');
   const resultMenuButton = document.getElementById('battle-result-menu-button');
   const bossRevivalOverlay = document.getElementById('boss-revival-overlay');
   if (bossRevivalOverlay) {
    bossRevivalOverlay.style.display = bossRevivalInProgress ? 'flex' : 'none';
   }

   if (gameOver) {
    const playerWon = battleResultStats && battleResultStats.result === 'win';
    winner.innerHTML = '';

    if (victoryResult) {
     victoryResult.innerHTML = getBattleResultHtml();
    }

    if (resultHeading) {
     resultHeading.textContent = playerWon ? '勝利！' : '敗北…';
    }

    if (resultMessage) {
     resultMessage.textContent = playerWon
      ? 'リザルトを確認して、次のレベルへ進みます。'
      : 'リザルトを確認して、メニュー画面へ戻ります。';
    }

    if (resultNextButton) {
     resultNextButton.style.display = playerWon ? '' : 'none';
    }

    if (resultMenuButton) {
     resultMenuButton.style.display = playerWon ? 'none' : '';
    }

    if (victoryActions) {
     victoryActions.classList.toggle('defeat-result-modal', !playerWon);
     victoryActions.style.display = (playerWon && (pendingPassiveChoice || pendingShopChoice || pendingRandomEvent)) ? 'none' : 'flex';
    }
   } else {
    if (victoryResult) {
     victoryResult.innerHTML = '';
    }
    winner.innerHTML = '';
   if (victoryActions) {
     victoryActions.classList.remove('defeat-result-modal');
     victoryActions.style.display = 'none';
    }
   }
   showPendingRelicRewardModalIfNeeded();
  }

  window.showCollectionScreen = showCollectionScreen;
window.showPetLibraryScreen = showPetLibraryScreen;
  window.showCardLibraryScreen = showCardLibraryScreen;
